// MIT. Original SEC edition -> retained Analysis source-document input.
// Uses the maintained SEC parser and local SF31 saveBytes writer.
import {readFile,lstat,mkdir,realpath} from 'node:fs/promises';
import {resolve,join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';

const PREFIX='stellar/scf-starforge-20261009/';
const SELF_PATH=PREFIX+'sf88-operator-buyer-cli/python/examples/sec_source_document.mjs';
const SEC_PATH=PREFIX+'sf30-seller-sdk/sec-edgar/source.mjs';
const REPOSITORY='woahwhattheheck/public-commons-sprint-2026';
const MAX=32*1024*1024;
const sha=raw=>createHash('sha256').update(raw).digest('hex');
const gitBlob=raw=>createHash('sha1').update(Buffer.from('blob '+raw.length+'\0')).update(raw).digest('hex');
const json=value=>Buffer.from(JSON.stringify(value)+'\n');
const need=(condition,code)=>{if(!condition)throw Object.assign(new Error(code),{code});};
const blobUrl=(repository,blob)=>'https://api.github.com/repos/'+repository+'/git/blobs/'+blob;

export const FACT_COLUMNS=Object.freeze({
 cik:'cik',entity_name:'entityName',taxonomy:'taxonomy',concept:'concept',label:'label',unit:'unit',
 value_text:'value',value_type:'valueType',period_start:'start',period_end:'end',accession:'accession',
 filed:'filed',form:'form',fiscal_year:'fy',fiscal_period:'fp',frame:'frame',
 source_index:'sourceIndex',unit_index:'unitIndex'
});
export const FILING_COLUMNS=Object.freeze({
 cik:'cik',entity_name:'entityName',accession:'accession',filed:'filed',form:'form',
 report_date:'reportDate',acceptance_datetime:'acceptanceDateTime',primary_document:'primaryDocument',
 description:'primaryDocDescription',size_bytes:'size',is_xbrl:'isXBRL',is_inline_xbrl:'isInlineXBRL',
 is_xbrl_numeric:'isXBRLNumeric',core_type:'coreType',items:'items',act:'act',file_number:'fileNumber',
 film_number:'filmNumber',document_url:'documentUrl',source_index:'sourceIndex'
});
export const SOURCE_COLUMNS=Object.freeze([
 'edition_id','source_sha256','source_url','captured_at','capture_scope'
]);

async function regular(path,maximum=MAX){
 const info=await lstat(path);
 need(info.isFile()&&!info.isSymbolicLink()&&info.size<=maximum,'SEC_ANALYSIS_REGULAR_SOURCE_REQUIRED');
 const bytes=await readFile(path);
 need(bytes.length===info.size&&bytes.length<=maximum,'SEC_ANALYSIS_SOURCE_CHANGED');
 return bytes;
}
async function directory(path,{create=false}={}){
 const absolute=resolve(path);
 if(create)await mkdir(absolute,{recursive:true,mode:0o700});
 const info=await lstat(absolute);
 need(info.isDirectory()&&!info.isSymbolicLink(),'SEC_ANALYSIS_DIRECTORY_REQUIRED');
 return realpath(absolute);
}
function scalar(value){
 if(value===undefined||value===null)return null;
 need(['string','number','boolean'].includes(typeof value),'SEC_ANALYSIS_ORIGINAL_SCALAR_REQUIRED');
 if(typeof value==='number')need(Number.isSafeInteger(value),'SEC_ANALYSIS_UNSAFE_ORIGINAL_INTEGER');
 return value;
}
function mappedRows(edition){
 const fields=edition.record.kind==='facts'?FACT_COLUMNS:FILING_COLUMNS;
 return edition.rows.map(row=>{
  const output={};
  for(const [name,original] of Object.entries(fields)){
   const value=row[original];
   // The native SEC parser retains each JSON numeric token for a fact as text.
   // Boolean/string facts retain their type label alongside their exact text.
   output[name]=name==='value_text'?(typeof value==='string'?value:JSON.stringify(value)):scalar(value);
  }
  return {...output,edition_id:edition.record.id,source_sha256:edition.record.sourceSha256,
   source_url:edition.record.sourceUrl,captured_at:edition.record.capturedAt,capture_scope:edition.record.scope};
 });
}
function scopeDescription(record){
 if(record.kind==='facts')return 'Every fact retained in this original companyfacts response. Units, periods, filing dates and repeated reported values remain separate. This capture is the publisher response at the recorded capture time.';
 const history=record.historyFiles??[];
 if(record.scope==='submissions-history')return 'Every filing in this specific original historical submissions file. Other recent or historical submissions files are outside this selected scope.';
 return 'Every filing in this original recent-submissions response. '+
  (history.length?'The source lists '+history.length+' additional historical file(s), retained in the original edition metadata but not acquired by this transformation. '+
   history.map(item=>[item.name,item.filingCount===null?'count unspecified':String(item.filingCount)+' filings',item.filingFrom??'',item.filingTo??''].filter(Boolean).join(' · ')).join('; '):
   'The original source lists no additional historical file in this capture.');
}
async function exactWriter(prepare,destination,bytes,contentType){
 try{
  const old=await regular(destination,Math.max(MAX,bytes.length));
  need(old.equals(bytes),'SEC_ANALYSIS_EXISTING_FILE_CHANGED');
  return;
 }catch(error){if(error.code!=='ENOENT')throw error;}
 const writer=await prepare({destination,maxBytes:MAX,timeoutMs:300000,
  expectedBytes:bytes.length,expectedSha256:sha(bytes),expectedContentType:contentType});
 await writer.saveBytes(bytes,{contentType});
}
export async function prepareSecDocument({checkout,store:sourceDirectory,editionId,out,expectedSourceBlob}){
 need(typeof checkout==='string'&&typeof sourceDirectory==='string'&&typeof out==='string',
  'SEC_ANALYSIS_SOURCE_SELECTION_REQUIRED');
 need(typeof editionId==='string'&&/^[A-Za-z0-9][A-Za-z0-9_-]{0,95}$/.test(editionId),'SEC_ANALYSIS_EDITION_REQUIRED');
 const root=await directory(checkout),origin=await directory(sourceDirectory);
 // Read/open is allowed only for an existing original store. Its constructor
 // therefore cannot silently create a new empty capture selection.
 await directory(join(origin,'editions'));await directory(join(origin,'blobs'));
 const nativePath=join(root,SEC_PATH),nativeBytes=await regular(nativePath,1024*1024);
 const nativeBlob=gitBlob(nativeBytes);
 need(expectedSourceBlob===undefined||expectedSourceBlob===nativeBlob,'SEC_ANALYSIS_SELECTED_PARSER_CHANGED');
 const bridgeBytes=await regular(fileURLToPath(import.meta.url),1024*1024);
 const bridgeBlob=gitBlob(bridgeBytes);
 const [{openEdgarStore},{prepareBuyerResponseFile}]=await Promise.all([
  import(pathToFileURL(nativePath)),
  import(pathToFileURL(join(root,PREFIX+'sf31-buyer-client/response-file.mjs')))
 ]);
 const original=await openEdgarStore(origin);
 try{
  const editionPath=join(origin,'editions',editionId+'.json');
  const editionBytes=await regular(editionPath,1024*1024);
  const edition=await original.getEdition(editionId,{includeRows:true});
  need(JSON.stringify(JSON.parse(editionBytes))===JSON.stringify(edition.record),
   'SEC_ANALYSIS_EDITION_CHANGED');
  const capture=await original.readRaw(editionId);
  need(capture.length===edition.record.sourceBytes&&sha(capture)===edition.record.sourceSha256,
   'SEC_ANALYSIS_CAPTURE_CHANGED');
  need(edition.rows.length===edition.record.recordCount,'SEC_ANALYSIS_ROW_COUNT_CHANGED');
  const rows=mappedRows(edition);
  const represented={
   schema:'stellar-forge.sec-analysis-records.v1',
   source:{...edition.record,parser:{path:SEC_PATH,blob:nativeBlob,sha256:sha(nativeBytes)},
    projection:{schema:'stellar-forge.sec-analysis-fields.v1',path:SELF_PATH,blob:bridgeBlob,
     sha256:sha(bridgeBytes),fields:edition.record.kind==='facts'?FACT_COLUMNS:FILING_COLUMNS}},
   rowCount:rows.length,rows
  };
  const document=json(represented);
  need(document.length<=MAX,'SEC_ANALYSIS_DOCUMENT_EXCEEDS_JSON_READER_LIMIT');
  const target=await directory(out,{create:true});await directory(join(target,'files'),{create:true});
  const put=async(bytes,extension,contentType)=>{
   const digest=sha(bytes),path='files/'+digest+'.'+extension;
   await exactWriter(prepareBuyerResponseFile,join(target,path),bytes,contentType);
   return {path,bytes:bytes.length,sha256:digest,contentType};
  };
  const analytical=await put(document,'json','application/json');
  const raw=await put(capture,'json','application/json');
  const recordFile=await put(editionBytes,'json','application/json');
  const parserFile=await put(nativeBytes,'txt','text/plain');
  const bridgeFile=await put(bridgeBytes,'txt','text/plain');
  need((await regular(editionPath,1024*1024)).equals(editionBytes),'SEC_ANALYSIS_EDITION_CHANGED');
  need((await regular(nativePath,1024*1024)).equals(nativeBytes),'SEC_ANALYSIS_PARSER_SOURCE_CHANGED');
  const manifest={
   schema:'stellar-forge.analysis-source-document.v1',
   title:edition.record.entityName.slice(0,100)+' · '+edition.record.kind+' · '+edition.record.id,
   format:'json',document:analytical,
   originals:[
    {...raw,role:'sec-original-capture',sourceUrl:edition.record.sourceUrl},
    {...recordFile,role:'sec-edition-metadata',sourceUrl:edition.record.sourceUrl},
    {...parserFile,role:'sec-native-parser-source',sourceUrl:blobUrl(REPOSITORY,nativeBlob)},
    {...bridgeFile,role:'sec-analysis-bridge-source',sourceUrl:blobUrl(REPOSITORY,bridgeBlob)}
   ],
   provenance:{kind:'public-source',publisher:'U.S. Securities and Exchange Commission',
    capturedAt:edition.record.capturedAt,sourceUrl:edition.record.sourceUrl,
    scope:edition.record.scope+' · CIK'+edition.record.cik,
    description:scopeDescription(edition.record),
    transform:{name:'Original SEC edition to Analysis source-document fields v1',
     sourceUrl:blobUrl(REPOSITORY,bridgeBlob),sha256:sha(bridgeBytes)}},
   complete:true
  };
  const manifestBytes=json(manifest);
  await exactWriter(prepareBuyerResponseFile,join(target,'source.json'),manifestBytes,'application/json');
  return {schema:'stellar-forge.sec-analysis-preparation.v1',edition:edition.record,
   rows:rows.length,fields:[...Object.keys(edition.record.kind==='facts'?FACT_COLUMNS:FILING_COLUMNS),...SOURCE_COLUMNS],
   directory:target,manifest:join(target,'source.json'),documentId:sha(manifestBytes),
   documentBytes:document.length,documentSha256:sha(document),
   parserBlob:nativeBlob,bridgeBlob,scope:manifest.provenance};
 }finally{await original.close();}
}
function argumentsFrom(argv){
 const options={};
 for(let i=0;i<argv.length;i+=2){
  const key=argv[i],value=argv[i+1];
  need(['--checkout','--store','--edition','--out','--expected-source-blob'].includes(key)&&value!==undefined,
   'SEC_ANALYSIS_CLI_ARGUMENT_INVALID');
  need(!(key in options),'SEC_ANALYSIS_CLI_ARGUMENT_REPEATED');options[key]=value;
 }
 return {checkout:options['--checkout'],store:options['--store'],editionId:options['--edition'],
  out:options['--out'],expectedSourceBlob:options['--expected-source-blob']};
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 if(process.argv.includes('--help')){
  process.stdout.write('node sec_source_document.mjs --checkout ORIGINAL_CHECKOUT --store ORIGINAL_SEC_STORE --edition ORIGINAL_EDITION_ID --out PRIVATE_DOCUMENT_DIRECTORY [--expected-source-blob GIT_SHA]\n');
 }else prepareSecDocument(argumentsFrom(process.argv.slice(2)))
  .then(value=>process.stdout.write(JSON.stringify(value,null,2)+'\n'))
  .catch(error=>{process.stderr.write((error.code??error.message)+'\n');process.exitCode=1;});
}

// SPDX-License-Identifier: MIT
// The original read-only SF100 scanner, reached through the existing Python Runtime.
import {realpath,lstat} from 'node:fs/promises';
import {join,resolve} from 'node:path';
import {scan} from '../../sf100-buyer-dataset-delivery/deliver.mjs';
import {initializationDirectory as directory} from '../initialization.mjs';
import {need} from '../config.mjs';

async function main(args){
  need(args.length===2&&args[0]==='--room'&&resolve(args[1])===args[1],
    'FINALIZED_DATASET_ROOM_REQUIRED');
  const room=args[1];await directory(room);await directory(join(room,'pages'));
  const value=await scan(room,{retainPayload:false});
  need(value.finalized===true&&value.nextCursor===null&&value.count===value.total,
    'FINALIZED_DATASET_COMPLETE_ROOM_REQUIRED');
  for(const path of [join(room,'session.json'),join(room,'manifest.json'),
    ...value.pages.map((_,index)=>join(room,'pages',String(index).padStart(5,'0')+'.json'))]){
    const info=await lstat(path);
    need(info.isFile()&&!info.isSymbolicLink()&&await realpath(path)===path,
      'FINALIZED_DATASET_SOURCE_PATH_CHANGED');
  }
  process.stdout.write(JSON.stringify({mode:'SF100_FINALIZED_SCAN',scan:value})+'\n');
}
main(process.argv.slice(2)).catch(error=>{
  const code=/^[A-Z0-9_]{1,120}$/.test(error?.code??'')?error.code:'FINALIZED_DATASET_SCAN_FAILED';
  process.stderr.write(JSON.stringify({error:code})+'\n');process.exitCode=1;
});

// MIT. Python object applications compose the original SF88 object session.
// Native queue attempts, terminal approval, recovery and assembly own all state.
import {constants} from 'node:fs';
import {open, lstat, realpath, link, unlink} from 'node:fs/promises';
import {dirname, isAbsolute, join, resolve} from 'node:path';
import {randomUUID} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {need} from '../config.mjs';
import {openWorkspace} from '../workspace.mjs';
import {selectObjectDescription} from '../object-description.mjs';
import {createObjectSession, inspectObjectSession, runObjectSession,
  recoverObjectSession, assembleObjectSession, accountObjectSession} from '../object-session.mjs';
import {renderObjectReport} from '../object-report.mjs';

const MODE = 'ORIGINAL_PYTHON_OBJECT';
const common = ['--session','--chunk-offset','--chunk-limit'];
const modes = {
  prepare:['--config','--workspace','--description','--object','--max-total-atomic','--chunk-bytes'],
  'prepare-explicit':['--config','--workspace','--bytes','--chunk-bytes','--snapshot',
    '--sha256','--content-type','--max-total-atomic'],
  inspect:[], run:['--workspace'], recover:[], assemble:['--out'],
  delivery:['--out'], download:['--out','--workspace'], report:['--out','--format'],
  accounting:['--workspace','--offset','--limit'],
  finalize:['--workspace','--offset','--limit','--outbox','--merchant-route'],
};
const safeCode = error => /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '') ? error.code :
  /^[A-Z0-9_]{1,120}$/.test(error?.message ?? '') ? error.message : 'OBJECT_APPLICATION_FAILED';
const print = value => process.stdout.write(JSON.stringify(value) + '\n');

function options(args) {
  const action = args[0], allowed = modes[action], values = Object.create(null);
  need(allowed && args.length % 2 === 1, 'OBJECT_APPLICATION_COMMAND_INVALID');
  for (let index=1; index<args.length; index+=2) {
    const name = args[index], value = args[index+1];
    need([...common,...allowed].includes(name) && !Object.hasOwn(values,name) &&
      typeof value === 'string' && value.length > 0 && !value.startsWith('--'),
    'OBJECT_APPLICATION_OPTION_INVALID');
    values[name] = value;
  }
  need(values['--session'], 'OBJECT_SESSION_REQUIRED');
  return {action,values};
}
function integer(value, fallback, minimum = 1, maximum = Number.MAX_SAFE_INTEGER) {
  if (value === undefined && fallback !== undefined) return fallback;
  need(typeof value === 'string' && /^(0|[1-9][0-9]{0,15})$/.test(value) &&
    Number.isSafeInteger(Number(value)) && Number(value) >= minimum && Number(value) <= maximum,
  'OBJECT_APPLICATION_INTEGER_INVALID');
  return Number(value);
}
function compact(report, offset, limit) {
  const {chunks,assemblies,...summary} = report;
  const items = chunks.slice(offset, offset + limit);
  const assemblyOffset = Math.max(0, assemblies.length - 25);
  return {report:summary,
    chunkPage:{offset,limit,total:chunks.length,items,
      nextOffset:offset + items.length < chunks.length ? offset + items.length : null},
    assemblyPage:{offset:assemblyOffset,total:assemblies.length,items:assemblies.slice(assemblyOffset)}};
}
function delivery(report, receipt) {
  need(report.status === 'COMPLETE', 'OBJECT_COMPLETE_SESSION_REQUIRED');
  need(receipt && ['SAVED','RECORDED'].includes(receipt.status) &&
    receipt.sessionId === report.sessionId && receipt.configurationSha256 === report.configurationSha256 &&
    receipt.snapshot === report.expectedSnapshot && receipt.bytes === report.bytes &&
    receipt.sha256 === report.objectSha256, 'OBJECT_ASSEMBLY_BINDING_INVALID');
  return {status:receipt.status, file:{path:receipt.destination,bytes:receipt.bytes,sha256:receipt.sha256},
    assembly:receipt, sessionId:report.sessionId, snapshot:report.expectedSnapshot,
    fileRevalidated:receipt.fileRevalidated === true};
}
async function newDestination(destination) {
  need(typeof destination === 'string' && isAbsolute(destination) &&
    destination === resolve(destination) && !destination.includes('\0'), 'OBJECT_OUTPUT_ABSOLUTE_REQUIRED');
  const parent = dirname(destination), info = await lstat(parent);
  need(info.isDirectory() && !info.isSymbolicLink() && await realpath(parent) === parent &&
    (process.platform === 'win32' || (info.mode & 0o077) === 0 &&
      (typeof process.getuid !== 'function' || info.uid === process.getuid())),
  'OBJECT_OUTPUT_PRIVATE_DIRECTORY_REQUIRED');
  try { await lstat(destination); }
  catch (error) { if (error.code === 'ENOENT') return; throw error; }
  need(false, 'OBJECT_DESTINATION_EXISTS');
}
async function saveReport(destination, bytes) {
  await newDestination(destination);
  const temporary = join(dirname(destination), '.object-report-' + randomUUID());
  const file = await open(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL |
    (constants.O_NOFOLLOW ?? 0), 0o600);
  try {
    try { await file.writeFile(bytes); await file.sync(); } finally { await file.close(); }
    await link(temporary, destination);
    if (process.platform !== 'win32') {
      const parent = await open(dirname(destination), constants.O_RDONLY);
      try { await parent.sync(); } finally { await parent.close(); }
    }
  } finally { await unlink(temporary).catch(() => {}); }
}

export async function main(args = process.argv.slice(2)) {
  const {action,values:v} = options(args), directory = v['--session'];
  const offset = integer(v['--chunk-offset'],0,0), limit = integer(v['--chunk-limit'],50,1,250);
  const controller = new AbortController();
  const interrupt = () => {process.exitCode=130; controller.abort();};
  const terminate = () => {process.exitCode=143; controller.abort();};
  let report, saved, output;
  if (action === 'accounting' || action === 'finalize') {
    process.once('SIGINT',interrupt); process.once('SIGTERM',terminate);
    try {
      report=await accountObjectSession(directory,{workspace:v['--workspace'],
        offset:integer(v['--offset'],0,0),limit:integer(v['--limit'],100,1,250),
        finalize:action==='finalize',signal:controller.signal,
        outbox:v['--outbox'],merchantRoute:v['--merchant-route']});
    } finally {process.off('SIGINT',interrupt);process.off('SIGTERM',terminate);}
    if(!process.exitCode&&action==='finalize'&&report.entries.some(entry=>
      !['FINALIZED','IDEMPOTENT_FINALIZED','NO_PAYMENT_REQUIRED','NOT_ATTEMPTED'].includes(entry.outcome)))
      process.exitCode=2;
    const result={mode:MODE,action,report};print(result);return result;
  }
  if (action === 'prepare' || action === 'prepare-explicit') {
    need(v['--config'] || v['--workspace'], 'OBJECT_CONFIG_OR_WORKSPACE_REQUIRED');
    need(v['--max-total-atomic'], 'OBJECT_TOTAL_BUDGET_REQUIRED');
    // This original open does not read keys or import a signer in review mode.
    const configPath = v['--config'] ?? (await openWorkspace(['--dir',v['--workspace']], {execute:false})).configPath;
    let selected;
    if (action === 'prepare') {
      need(v['--description'] && v['--object'], 'OBJECT_DESCRIPTION_AND_SELECTION_REQUIRED');
      selected = await selectObjectDescription({descriptionPath:v['--description'],objectId:v['--object'],
        configPath,chunkBytes:v['--chunk-bytes'] === undefined ? undefined : integer(v['--chunk-bytes'])});
    } else selected = {bytes:integer(v['--bytes']),chunkBytes:integer(v['--chunk-bytes']),
      expectedSnapshot:v['--snapshot'],expectedSha256:v['--sha256'] ?? null,
      expectedContentType:v['--content-type'] ?? null};
    report = await createObjectSession({directory,configPath,workspace:v['--workspace'] ?? null,
      maxTotalAtomic:v['--max-total-atomic'],...selected});
  } else if (action === 'recover') report = await recoverObjectSession(directory);
  else if (action === 'assemble') {
    need(v['--out'], 'OBJECT_OUTPUT_REQUIRED');
    report = await assembleObjectSession(directory,v['--out']);
    saved = delivery(report,report.assembly);
  } else if (action === 'run' || action === 'download') {
    if (action === 'download') {
      need(v['--out'], 'OBJECT_OUTPUT_REQUIRED');
      report = await inspectObjectSession(directory);
      const previous = report.assemblies.find(value => value.destination === v['--out']);
      if (previous) saved = delivery(report,previous);
      else await newDestination(v['--out']); // Refuse a known bad destination before any request.
    }
    if (!saved) {
      process.once('SIGINT',interrupt); process.once('SIGTERM',terminate);
      try {
        report = await runObjectSession(directory,{signal:controller.signal,
          ...(v['--workspace'] === undefined ? {} : {workspace:v['--workspace']})});
        if (action === 'download' && report.status === 'COMPLETE' && !controller.signal.aborted) {
          report = await assembleObjectSession(directory,v['--out']);
          saved = delivery(report,report.assembly);
        }
      } finally {process.off('SIGINT',interrupt); process.off('SIGTERM',terminate);}
    }
  } else {
    report = await inspectObjectSession(directory);
    if (action === 'delivery') {
      const receipt = v['--out'] === undefined ? report.assembly :
        report.assemblies.find(value => value.destination === v['--out']);
      need(receipt, 'OBJECT_ASSEMBLY_NOT_RECORDED');
      saved = delivery(report,receipt);
    }
    if (action === 'report') {
      need(v['--out'], 'OBJECT_OUTPUT_REQUIRED');
      const format = v['--format'] ?? 'html';
      need(['html','json'].includes(format), 'OBJECT_REPORT_FORMAT_INVALID');
      await saveReport(v['--out'], format === 'html' ? renderObjectReport(report) : JSON.stringify(report,null,2)+'\n');
      output = {path:v['--out'],format,scope:'COMPLETE_ORIGINAL_OBJECT_REPORT'};
    }
  }
  const result = {mode:MODE,action,...compact(report,offset,limit),
    ...(saved ? {delivery:saved} : {}),...(output ? {output} : {})};
  if (!process.exitCode && ['run','download'].includes(action) &&
    ['RECONCILIATION_REQUIRED','INTERRUPTED'].includes(report.status)) process.exitCode=2;
  print(result);
  return result;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => {process.stderr.write(JSON.stringify({error:safeCode(error)})+'\n'); process.exitCode ||= 1;});

#!/usr/bin/env node
// One real browser receiving over the original private VGI operator.
import fs from 'node:fs';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import crypto from 'node:crypto';

const configuration=JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const directory=configuration.directory;
fs.mkdirSync(directory,{recursive:true,mode:0o700});
const output=path.join(directory,'result.json');
const require=(condition,message)=>{if(!condition)throw new Error(message);};
const save=(name,value)=>{
  const destination=path.join(directory,name),temporary=destination+'.pending';
  fs.writeFileSync(temporary,JSON.stringify(value,null,2)+'\n',{mode:0o600});
  fs.renameSync(temporary,destination);
};
if(fs.existsSync(output)){
  const prior=JSON.parse(fs.readFileSync(output,'utf8'));
  require(prior.operation===configuration.operation&&prior.stage===configuration.stage
    &&prior.workspace_id===configuration.workspace_id&&prior.passed===true,
    'The original browser receiving selection changed');
  process.stdout.write(JSON.stringify(prior)+'\n');
  process.exit(0);
}

const parsed=new URL(configuration.url),capability=parsed.hash.slice(1);
require(parsed.hostname==='127.0.0.1'&&parsed.protocol==='http:'&&capability,
  'Use the original private loopback launch URL');
const authHeaders={'X-DuckDB-Capability':capability,
  'X-DuckDB-Workspace-ID':configuration.workspace_id};
const requestFile=path.join(directory,'original-requests.json');
let requests=fs.existsSync(requestFile)?JSON.parse(fs.readFileSync(requestFile,'utf8')):[];
const pageErrors=[];
const playwright=await import(pathToFileURL(configuration.playwright).href);
const context=await playwright.chromium.launchPersistentContext(configuration.profile,{
  executablePath:configuration.chromium,headless:true,
  viewport:{width:1440,height:1050},acceptDownloads:true,
  args:['--no-sandbox','--disable-dev-shm-usage']
});
const page=await context.newPage();
page.on('pageerror',error=>pageErrors.push({name:error.name,message:error.message}));
await page.route('**/api/**',async route=>{
  const request=route.request();
  if(request.method()==='POST'){
    const url=new URL(request.url()),body=request.postData()||'';
    const signature=crypto.createHash('sha256').update(url.pathname+'\n'+body).digest('hex');
    let row=requests.find(x=>x.signature===signature);
    if(!row){
      row={signature,path:url.pathname,body,created_at:new Date().toISOString(),state:'PREPARED'};
      requests.push(row);save('original-requests.json',requests);
    }
    const response=await route.fetch();
    const text=await response.text();
    row.status=response.status();row.returned_at=new Date().toISOString();
    try{row.result=JSON.parse(text);}catch{row.result={complete_json:false};}
    row.state=response.ok()?'COMPLETE':'REVIEW_REQUIRED';
    save('original-requests.json',requests);
    await route.fulfill({response,body:text});
  }else await route.continue();
});
const api=async(route,body)=>{
  const result=await context.request.fetch(parsed.origin+route,{
    method:body===undefined?'GET':'POST',
    headers:{...authHeaders,...(body===undefined?{}:{'Content-Type':'application/json'})},
    ...(body===undefined?{}:{data:body}),timeout:180000});
  const value=await result.json();
  require(result.ok(),'Original operator returned '+result.status()+': '+(value.error||'unknown'));
  return value;
};
const current=()=>api('/api/vgi/state');
const settle=async()=>{
  await page.waitForFunction(()=>!document.body.classList.contains('busy'),null,{timeout:180000});
  const error=page.locator('#error');
  require(!(await error.isVisible()),await error.textContent()||'Original UI operation failed');
};
const click=async selector=>{
  await page.locator(selector).click();
  await settle();
};
let result;
try{
  // Complete only original payloads whose browser reply was interrupted.
  for(const request of requests.filter(x=>x.state==='PREPARED')){
    const body=JSON.parse(request.body);
    request.result=await api(request.path,body);
    request.state='COMPLETE';request.returned_at=new Date().toISOString();
    save('original-requests.json',requests);
  }
  await page.goto(configuration.url,{waitUntil:'domcontentloaded'});
  await page.locator('#main').waitFor({state:'visible',timeout:180000});
  await settle();
  let state=await current();
  require(state.workspace_id===configuration.workspace_id,'The original workspace changed');
  if(configuration.stage==='publish'){
    const target={catalog_name:'purchased_results',label:'Retained Svenska kraftnät results',
      principals:[configuration.principal],allow_local:false};
    if(state.configuration.catalog_name!==target.catalog_name
      ||state.configuration.label!==target.label
      ||state.configuration.allow_local!==false
      ||state.configuration.principals.length!==1
      ||state.configuration.principals[0]!==configuration.principal){
      await click('#vgi-access-tab');
      await page.locator('#catalog-name').fill(target.catalog_name);
      await page.locator('#catalog-label').fill(target.label);
      await page.locator('#principals').fill(configuration.principal);
      await page.locator('#allow-local').uncheck();
      await click('#save-configuration');
      state=await current();
    }
    require(state.configuration.catalog_name===target.catalog_name
      &&state.configuration.principals.length===1
      &&state.configuration.principals[0]===configuration.principal
      &&state.configuration.allow_local===false,'The original access form did not retain its selection');
    let head=state.tables.find(x=>x.name===configuration.table_name);
    if(!head){
      await click('#vgi-publish-tab');
      await page.locator('#export-select').selectOption(configuration.export_id);
      await page.locator('#batch-rows').fill('16');
      await page.locator('#publish-table').fill(configuration.table_name);
      await click('#review-export');
      await page.locator('#publish-result').waitFor({state:'visible'});
      await click('#publish-result');
      state=await current();
      head=state.tables.find(x=>x.name===configuration.table_name);
    }
    require(head?.active===true,'The original published table is not active');
    const publication=await api('/api/vgi/publications/'+head.publication_id);
    require(publication.source.export_id===configuration.export_id
      &&publication.rows===32&&publication.batches.length===2
      &&publication.batches.every(x=>x.rows===16),'The original reviewed publication changed');
    await click('#vgi-catalog-tab');
    await page.getByRole('button',{name:'Inspect',exact:true}).first().click();
    await settle();
    await page.screenshot({path:path.join(directory,'publication.png'),fullPage:true});
    await click('#vgi-runtime-tab');
    state=await current();
    if(state.runtime.observed!=='RUNNING'){
      require(state.installed_runtime.ready===true,'The selected native vendor cohort is not installed');
      await page.locator('#listen-host').fill('127.0.0.1');
      await page.locator('#listen-port').fill('0');
      await click('#start-service');
      state=await current();
    }
    require(state.runtime.observed==='RUNNING'&&state.runtime.owned===true,
      'The original listener did not retain its actual lifetime');
    await page.screenshot({path:path.join(directory,'listener.png'),fullPage:true});
    result={publication_id:publication.publication_id,table:head,
      configuration:state.configuration,
      runtime:{request_id:state.runtime.request_id,address:state.runtime.address,
        catalog:state.runtime.catalog}};
  }else if(configuration.stage==='handover'){
    await click('#vgi-recovery-tab');
    const original=requests.find(x=>x.path==='/api/handoffs'&&x.state==='COMPLETE');
    let handoff=original?.result;
    if(!handoff){
      await click('#create-handoff');
      handoff=requests.findLast(x=>x.path==='/api/handoffs'&&x.state==='COMPLETE')?.result;
    }
    require(handoff?.files?.some(x=>x.name==='warehouse.duckdb'),
      'The original full warehouse handover did not return');
    await page.getByRole('button',{name:'Read latest history',exact:true}).click();
    await settle();
    await page.screenshot({path:path.join(directory,'handover.png'),fullPage:true});
    const warehouse=handoff.files.find(x=>x.name==='warehouse.duckdb');
    const response=await context.request.get(parsed.origin+'/api/exports/'
      +encodeURIComponent(handoff.export_id)+'/file?name=warehouse.duckdb',
      {headers:authHeaders,timeout:180000});
    require(response.ok(),'The original handover download did not complete');
    const bytes=await response.body();
    require(bytes.length===warehouse.bytes
      &&crypto.createHash('sha256').update(bytes).digest('hex')===warehouse.sha256,
      'The complete downloaded native warehouse changed');
    result={handoff,download:{name:warehouse.name,bytes:bytes.length,sha256:warehouse.sha256}};
  }else if(configuration.stage==='restored'){
    const head=state.tables.find(x=>x.name===configuration.table_name);
    require(head?.publication_id===configuration.publication_id&&head.active,
      'The restored catalog head changed');
    await click('#vgi-catalog-tab');
    await page.getByRole('button',{name:'Inspect',exact:true}).first().click();
    await settle();
    const publication=await api('/api/vgi/publications/'+configuration.publication_id);
    require(publication.rows===32&&publication.batches.length===2,
      'The restored original publication changed');
    await page.screenshot({path:path.join(directory,'restored-catalog.png'),fullPage:true});
    await click('#vgi-recovery-tab');
    await page.getByRole('button',{name:'Read latest history',exact:true}).click();
    await settle();
    await page.screenshot({path:path.join(directory,'restored-history.png'),fullPage:true});
    result={publication_id:publication.publication_id,
      service_revision:state.revision,retained_publications:state.publications.length};
  }else throw new Error('Select the original supported receiving stage');
  require(pageErrors.length===0,'The actual operator page reported a JavaScript error');
  result={operation:configuration.operation,stage:configuration.stage,passed:true,
    completed_at:new Date().toISOString(),workspace_id:state.workspace_id,
    service_id:state.service_id,page_error_count:pageErrors.length,
    original_requests:requests.map(x=>({signature:x.signature,path:x.path,state:x.state,status:x.status})),
    ...result};
  save('result.json',result);
}finally{
  save('page-errors.json',pageErrors);
  await context.close();
}
process.stdout.write(JSON.stringify(result)+'\n');

// MIT. Python calls the original Research SDK through the existing Node runtime.
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {readResearchHostFile} from '../research-dossiers/workspace-files.mjs';
import {ResearchWorkspaceClient} from '../research-dossiers/workspace-client.mjs';
import {need,object,parseJson} from '../node/store.mjs';
import {createResearchDocumentSource} from './research-document-source.mjs';
import {citationReviewInput,citationDigest} from '../research-dossiers/citation-updates.mjs';
import {exportCitationFile,receiveCitationFile} from './research-citation-delivery.mjs';
import {eligibilityConsumerInput,readEligibility,submitEligibility,exportEligibility} from '../research-dossiers/eligibility-consumer.mjs';
import {exportEligibilityDeliveryFile,receiveEligibilityFile} from './research-eligibility-delivery.mjs';

const MODE='RESEARCH_WORKSPACE_BRIDGE',SCHEMA='stellar-forge.research-python-call.v1';
const safeCode=value=>typeof value==='string'&&/^[A-Z0-9_]{1,120}$/.test(value)?value:'RESEARCH_NATIVE_CALL_FAILED';
function errorRecord(error){
  const record={error:safeCode(error?.code)};
  for(const key of ['status','outcomeUnknown','method','route','recovery','requestId','operationId',
    'destinationPublished','file','sourceCleanupFailed','clientWarnings','openAlexImport'])
    if(error?.[key]!==undefined)record[key]=error[key];
  return record;
}
async function dispatch(client,action,input,signal){
  const {dossierId,operationId,selection,options={},body={}}=input;
  const requestOptions={...options,signal};
  switch(action){
    case 'status':return client.status(requestOptions);
    case 'dossiers':return client.list(options);
    case 'metadata':return client.metadata(dossierId,options);
    case 'section':return client.section(dossierId,options);
    case 'create-dossier':return client.createDossier(body);
    case 'update-dossier':return client.updateDossier(dossierId,body);
    case 'add-question':return client.addQuestion(dossierId,body);
    case 'update-question':return client.updateQuestion(dossierId,input.questionId,body);
    case 'add-finding':return client.addFinding(dossierId,body);
    case 'update-finding':return client.updateFinding(dossierId,input.findingId,body);
    case 'select-evidence':return client.selectEvidence(dossierId,body);
    case 'update-selection':return client.updateSelection(dossierId,body);
    case 'compare':return client.compare(dossierId,options);
    case 'eligibility':return readEligibility(client,dossierId,options);
    case 'eligibility-review':return submitEligibility(client,dossierId,body);
    case 'eligibility-export':return exportEligibility(client,dossierId,requestOptions);
    case 'eligibility-delivery-export':return exportEligibilityDeliveryFile(client,input);
    case 'citation-updates':return client.citationUpdates(dossierId,options);
    case 'citation-review':return client.reviewCitationUpdate(dossierId,body);
    case 'citation-export':return exportCitationFile(client,input);
    case 'export-dossier':return client.exportDossier(dossierId,requestOptions);
    case 'export-edition':return client.exportRetainedEdition(dossierId,input.editionId,requestOptions);
    case 'export-comparison':return client.exportComparison(dossierId,requestOptions);
    case 'reopen-dossier':return client.reopenFile(input.file,requestOptions);
    case 'receive-research-file':return client.receiveResearchFile(dossierId,body);
    case 'documents-list':return client.documents().list(dossierId,requestOptions);
    case 'documents-review':return client.documents().review(dossierId,selection,requestOptions);
    case 'documents-elements':return client.documents().elements(dossierId,body,requestOptions);
    case 'documents-receive':return client.documents().receive(dossierId,body,requestOptions);
    case 'documents-download':return client.documents().download(dossierId,{...body,...requestOptions});
    case 'pipelines-list':return client.pipelines().list(dossierId,requestOptions);
    case 'pipelines-operation':return client.pipelines().operation(dossierId,operationId,requestOptions);
    case 'pipelines-prepare':return client.pipelines().prepareFiles(dossierId,body,requestOptions);
    case 'pipelines-submit':return client.pipelines().submit(dossierId,operationId,body,requestOptions);
    case 'pipelines-refresh':return client.pipelines().refresh(dossierId,operationId,body,requestOptions);
    case 'pipelines-cancel':return client.pipelines().cancel(dossierId,operationId,body,requestOptions);
    case 'pipelines-provider-jobs':return client.pipelines().providerJobs(dossierId,operationId,body,requestOptions);
    case 'pipelines-reconcile':return client.pipelines().reconcile(dossierId,operationId,body,requestOptions);
    case 'pipelines-retain':return client.pipelines().retainOutput(dossierId,operationId,body,requestOptions);
    case 'pipelines-review':return client.pipelines().review(dossierId,selection,requestOptions);
    case 'pipelines-elements':return client.pipelines().elements(dossierId,body,requestOptions);
    case 'pipelines-receive':return client.pipelines().receive(dossierId,body,requestOptions);
    case 'pipelines-download-input':return client.pipelines().downloadInput(dossierId,operationId,input.inputId,requestOptions);
    case 'pipelines-download-output':return client.pipelines().downloadOutput(dossierId,operationId,input.outputId,requestOptions);
    case 'pipelines-download':return client.pipelines().downloadReceived(dossierId,{...body,...requestOptions});
    default:need(false,'RESEARCH_PYTHON_ACTION_INVALID');
  }
}
export async function runResearchCall(request,{signal}={}){
  need(object(request)&&request.schema===SCHEMA&&typeof request.action==='string'&&object(request.input),
    'RESEARCH_PYTHON_REQUEST_INVALID');
  if(request.action==='eligibility-input')
    return {mode:MODE,ok:true,workspaceId:null,result:eligibilityConsumerInput(request.input.request)};
  if(request.action==='eligibility-receive')
    return {mode:MODE,ok:true,workspaceId:null,result:await receiveEligibilityFile(request.input)};
  if(request.action==='citation-review-input'){
    need(Buffer.byteLength(JSON.stringify(request.input.request))<=16*1024*1024,'CITATION_REVIEW_INPUT_TOO_LARGE');
    const value=citationReviewInput(request.input.request);
    return {mode:MODE,ok:true,workspaceId:null,result:{request:value,sha256:citationDigest(value)}};
  }
  if(request.action==='citation-receive')
    return {mode:MODE,ok:true,workspaceId:null,result:await receiveCitationFile(request.input)};
  if(request.action==='analysis-source'){
    return {mode:MODE,ok:true,workspaceId:null,
      result:await createResearchDocumentSource(request.input)};
  }
  need(typeof request.connectionFile==='string','RESEARCH_CONNECTION_FILE_REQUIRED');
  need(request.expectedWorkspaceId===undefined||/^research_[a-f0-9]{64}$/.test(request.expectedWorkspaceId),
    'RESEARCH_WORKSPACE_ID_INVALID');
  const client=new ResearchWorkspaceClient({connectionFile:resolve(request.connectionFile),
    ...(request.expectedWorkspaceId?{expectedWorkspaceId:request.expectedWorkspaceId}:{})},
    {timeoutMs:request.timeoutMs??120000});
  let result;
  try{
    // Bind the original server/workspace before any selected write. Connection
    // credentials remain in its original private file and never enter results.
    const status=await client.status({signal});
    result={mode:MODE,ok:true,workspaceId:status.workspaceId,
      result:request.action==='status'?status:await dispatch(client,request.action,request.input,signal)};
  }catch(error){
    result={mode:MODE,ok:false,workspaceId:client.workspaceId,...errorRecord(error)};
  }finally{
    try{await client.close();}
    catch(error){
      if(result)result.sourceCleanupFailed=safeCode(error?.code);
      else throw error;
    }
  }
  return result;
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  let result,controller=new AbortController();
  const cancel=()=>controller.abort();
  process.once('SIGTERM',cancel);process.once('SIGINT',cancel);
  try{
    need(process.argv.length===4&&process.argv[2]==='--request','RESEARCH_PYTHON_REQUEST_FILE_REQUIRED');
    const request=parseJson(await readResearchHostFile(resolve(process.argv[3]),32*1024*1024,{privateFile:true}));
    result=await runResearchCall(request,{signal:controller.signal});
  }catch(error){result={mode:MODE,ok:false,...errorRecord(error)};}
  finally{process.removeListener('SIGTERM',cancel);process.removeListener('SIGINT',cancel);}
  process.stdout.write(JSON.stringify(result)+'\n');
  if(!result.ok){process.stderr.write(JSON.stringify({error:result.error})+'\n');process.exitCode=1;}
}

// MIT. Complete Python citation delivery through the original Research engine.
import {createHash} from 'node:crypto';
import {lstat,mkdtemp,rm} from 'node:fs/promises';
import {dirname,join,resolve,isAbsolute} from 'node:path';
import {openDossierStore} from '../research-dossiers/dossier.mjs';
import {citationDigest} from '../research-dossiers/citation-updates.mjs';
import {researchSummary} from '../research-dossiers/workspace-protocol.mjs';
import {readResearchHostFile,openResearchSource} from '../research-dossiers/workspace-files.mjs';
import {privateDirectory,withPrivateLock} from '../../sf30-seller-sdk/routescan/quota.mjs';
import {need,object,parseJson,writeJson,readJson} from '../node/store.mjs';

const SCHEMA='stellar-forge.citation-python-delivery.v1';
const LIMIT=256*1024*1024;
const same=(a,b)=>citationDigest(a)===citationDigest(b);
const absolute=value=>{
  need(typeof value==='string'&&isAbsolute(value)&&resolve(value)===value,'CITATION_ABSOLUTE_PATH_REQUIRED');
  return value;
};
async function exists(file){
  try{const s=await lstat(file);need(s.isFile()&&!s.isSymbolicLink(),'CITATION_FILE_TYPE_CHANGED');return true;}
  catch(error){if(error.code==='ENOENT')return false;throw error;}
}
async function pin(file){
  const source=await openResearchSource(absolute(file),LIMIT);
  try{return {file,bytes:source.bytes,sha256:source.sha256};}finally{await source.close();}
}
async function originalSelection(input){
  need(object(input)&&/^[a-f0-9]{64}$/.test(input.selectionSha256),'CITATION_SELECTION_REQUIRED');
  const raw=await readResearchHostFile(absolute(input.selectionFile),32*1024*1024,{sha256:input.selectionSha256});
  const value=parseJson(raw);
  need(value.schema===SCHEMA&&/^research_[a-f0-9]{64}$/.test(value.workspaceId)&&
    /^d_[a-f0-9-]{36}$/.test(value.dossierId)&&
    /^cu_[a-f0-9]{64}$/.test(value.noticeId)&&object(value.snapshots)&&Array.isArray(value.history),
    'CITATION_SELECTION_INVALID');
  for(const label of ['before','reviewed','current']){
    const item=value.snapshots[label];
    need(object(item)&&Number.isSafeInteger(item.revision)&&item.revision>=1&&
      item.metadata?.id===value.dossierId&&item.metadata.revision===item.revision&&
      item.detail?.dossier?.id===value.dossierId&&item.detail.dossier.revision===item.revision&&
      item.detail.detail?.noticeId===value.noticeId,'CITATION_SELECTION_INVALID');
  }
  need(value.review?.requestId===value.request?.requestId&&same(value.review.request,value.request)&&
    value.review.originalRevision===value.snapshots.before.revision&&
    value.review.revision===value.snapshots.reviewed.revision&&
    value.snapshots.current.revision>=value.snapshots.reviewed.revision,
    'CITATION_REVIEW_SELECTION_CHANGED');
  return value;
}
async function checkStore(store,selection,label){
  const selected=selection.snapshots[label],id=selection.dossierId,revision=selected.revision;
  const metadata=researchSummary(await store.getMetadata(id,{revision}));
  const history=await store.listRevisions(id,{revision});
  const detail=await store.citationUpdates(id,{revision,noticeId:selection.noticeId});
  need(same(metadata,selected.metadata),'CITATION_RECEIVED_METADATA_CHANGED');
  need(same(history,selection.history.filter(item=>item.revision<=revision)),'CITATION_RECEIVED_HISTORY_CHANGED');
  need(same(detail,selected.detail),'CITATION_RECEIVED_REVIEW_CHANGED');
  return {dossierId:id,revision,historySha256:citationDigest(history),
    detailSha256:citationDigest(detail),reviewId:selection.review.id,
    reviewPresent:detail.detail.reviews.some(item=>item.id===selection.review.id)};
}
async function importPortable(store,file,format,expected){
  need(expected&&/^[a-f0-9]{64}$/.test(expected.sha256),'CITATION_RETAINED_DIGEST_REQUIRED');
  if(format==='json'){
    const raw=await readResearchHostFile(file,LIMIT,{sha256:expected.sha256});
    need(raw.length===expected.bytes,'CITATION_EXPORT_BYTES_CHANGED');
    await store.reopen(parseJson(raw));
  }else{
    const source=await openResearchSource(file,LIMIT,{sha256:expected.sha256});
    try{need(source.bytes===expected.bytes,'CITATION_EXPORT_BYTES_CHANGED');
      await store.reopenStream(source.stream,{projection:'metadata'});}finally{await source.close();}
  }
}
async function checkPortable(file,format,selection,label,parent,expected){
  const temporary=await mkdtemp(join(parent,'.citation-inspect-'));
  try{
    const store=await openDossierStore(temporary);
    await importPortable(store,file,format,expected);
    return await checkStore(store,selection,label);
  }finally{await rm(temporary,{recursive:true,force:true});}
}
async function immutable(file,value){
  if(await exists(file)){const saved=await readJson(file,32*1024*1024);
    need(same(saved,value),'CITATION_RECEIPT_CHANGED');return saved;}
  try{await writeJson(file,value,{exclusive:true});return value;}
  catch(error){if(error.code!=='EEXIST')throw error;
    const saved=await readJson(file,32*1024*1024);need(same(saved,value),'CITATION_RECEIPT_CHANGED');return saved;}
}

/** Keep the first published bytes, including a lost original download reply. */
export async function exportCitationFile(client,input){
  const selection=await originalSelection(input),{label,format}=input;
  need(client.workspaceId===selection.workspaceId,'CITATION_WORKSPACE_CHANGED');
  need(['before','reviewed','current'].includes(label)&&['html','md','json','json.gz'].includes(format),
    'CITATION_EXPORT_SELECTION_INVALID');
  const file=absolute(input.file),parent=await privateDirectory(dirname(file));
  const root=await privateDirectory(join(parent,'.citation-exports'));
  const key=citationDigest({file}),slot=await privateDirectory(join(root,key));
  return withPrivateLock(slot,'export.lock',async()=>{
    const revision=selection.snapshots[label].revision;
    const identity={selectionSha256:input.selectionSha256,dossierId:selection.dossierId,
      label,revision,format,file};
    await immutable(join(slot,'selection.json'),identity);
    const receiptFile=join(slot,'receipt.json');
    if(await exists(receiptFile)){
      const saved=await readJson(receiptFile,65536);
      need(same(saved.identity,identity),'CITATION_EXPORT_SELECTION_CHANGED');
      need(await exists(file),'CITATION_RETAINED_EXPORT_MISSING');
      const current=await pin(file);
      need(current.bytes===saved.file.bytes&&current.sha256===saved.file.sha256,'CITATION_EXPORT_BYTES_CHANGED');
      return saved.file;
    }
    let artifact;
    if(await exists(file)){
      // Selection was retained before the original export. Validate that exact
      // published candidate against every selected history envelope; never
      // overwrite it or regenerate a portable archive with a later timestamp.
      artifact=await pin(file);
      if(format==='json'||format==='json.gz'){
        await checkPortable(file,format,selection,label,parent,artifact);
      }else{
        const temporary=await mkdtemp(join(parent,'.citation-report-'));
        try{
          const checked=await client.exportDossier(selection.dossierId,{
            revision,format,file:join(temporary,'report')});
          need(checked.revision===revision&&checked.bytes===artifact.bytes&&checked.sha256===artifact.sha256,
            'CITATION_EXPORT_BYTES_CHANGED');
        }finally{await rm(temporary,{recursive:true,force:true});}
      }
      artifact={...artifact,revision,contentType:format==='html'?'text/html; charset=utf-8':
        format==='md'?'text/markdown; charset=utf-8':format==='json'?'application/json':'application/gzip'};
    }else{
      artifact=await client.exportDossier(selection.dossierId,{revision,format,file});
      need(artifact.revision===revision,'CITATION_EXPORT_REVISION_CHANGED');
      if(format==='json'||format==='json.gz')await checkPortable(file,format,selection,label,parent,artifact);
    }
