JS = r'''"use strict";
const $=id=>document.getElementById(id);
if(location.hash.length>1){sessionStorage.setItem('sf-analysis-capability',location.hash.slice(1));history.replaceState(null,'',location.pathname);}
const capability=sessionStorage.getItem('sf-analysis-capability')||'';
$('workspace-link').href='/#'+capability;
const s={versions:[],profiles:[],versionNext:null,historyNext:null,document:null,column:null,notes:{},dirty:false,busy:false,active:null,comparison:null,workspaceId:null,pending:{run:null,review:null},pendingInvalid:false};
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);return n;}
function cell(tr,text){const td=node('td',text);tr.append(td);return td;}
function action(label,fn){const b=node('button',label);b.addEventListener('click',()=>act(fn));return b;}
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);}
function short(value){return String(value||'').slice(0,12);}
function text(value){return value==null?'—':value.type+': '+(value.text===''&&value.type==='text'?'[empty]':value.text)+(value.truncated?'… [preview]':'');}
function fact(parent,label,value){const d=node('div');d.append(node('b',label),node('span',value??'—'));parent.append(d);}
function controls(){for(const id of ['run','refresh','more-versions','more-history','save-review','save-frequency','compare','download-json','download-html','comparison-json','retry-run','retry-review','forget-pending'])$(id).disabled=s.busy;$('run').disabled||=Boolean(s.active)||!s.versions.length||s.pendingInvalid;$('save-review').disabled||=s.pendingInvalid;$('compare').disabled||=!$('before').value||!$('after').value;$('cancel').hidden=!s.active;}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Analysis-Capability':capability,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function pendingKey(){if(!s.workspaceId)throw Error('Reconnect to the original workspace first.');return 'sf-profile-pending:'+s.workspaceId;}
function renderPending(){const run=s.pending.run,review=s.pending.review;$('pending-panel').hidden=!(run||review||s.pendingInvalid);$('retry-run').hidden=!run;$('retry-review').hidden=!review;$('pending-info').textContent=s.pendingInvalid?'The retained browser request could not be read. It has not been replaced. Use the workspace history before explicitly forgetting this local copy.':[(run?'Profile request '+run.body.id+' for edition '+short(run.body.version_id)+'.':''),(review?'Review save '+review.body.id+' for profile '+review.profile_id+'.':'')].filter(Boolean).join(' ')+' A reply was not confirmed. Retry sends the exact original ID and body; it does not create a new scan or review.';}
function storePending(value){sessionStorage.setItem(pendingKey(),JSON.stringify(value));s.pending=value;s.pendingInvalid=false;renderPending();}
function loadPending(){const raw=sessionStorage.getItem(pendingKey());if(!raw){s.pending={run:null,review:null};renderPending();return;}try{const value=JSON.parse(raw),id=/^[a-f0-9]{32}$/,sha=/^[a-f0-9]{64}$/;if(!value||typeof value!=='object'||Array.isArray(value)||value.run&&(!id.test(value.run.body?.id)||!sha.test(value.run.body?.version_id))||value.review&&(!id.test(value.review.profile_id)||!id.test(value.review.body?.id)||!sha.test(value.review.body?.profile_sha256)))throw Error('Invalid retained request');s.pending={run:value.run||null,review:value.review||null};s.pendingInvalid=false;}catch{s.pendingInvalid=true;}renderPending();}
function newRequestId(){return crypto.randomUUID().replaceAll('-','');}
async function submitPendingRun(){const pending=s.pending.run;if(!pending)throw Error('No retained profile request.');const job=await api('/api/start/profile',pending.body);storePending({...s.pending,run:null});s.dirty=false;await loadHistory();if(job.status==='RUNNING'){s.active=job.id;message('Original profile request accepted: '+job.id);poll();}else if(job.status==='COMPLETE'){await openProfile(job.id);$('progress').textContent='COMPLETE';message('Reopened the completed original profile '+short(job.id)+'.');}else{message('Original profile is '+job.status+(job.error?': '+job.error:''),job.status==='FAILED');}}
async function submitPendingReview(){const pending=s.pending.review;if(!pending)throw Error('No retained review request.');await api('/api/profiles/'+pending.profile_id+'/review',pending.body);storePending({...s.pending,review:null});s.dirty=false;await openProfile(pending.profile_id);message('Original review save confirmed in the dataset database.');}
async function restorePendingDraft(){const pending=s.pending.review;if(!pending||s.document)return;await openProfile(pending.profile_id);s.notes={...pending.body.column_notes};$('decision').value=pending.body.decision;$('note').value=pending.body.note;markDirty();$('draft-state').textContent='Retained review draft · retry its original save';}
async function act(fn){if(s.busy)return;s.busy=true;controls();try{await fn();}catch(e){message(e.message,true);}finally{s.busy=false;controls();}}
function markDirty(){s.dirty=true;$('draft-state').textContent='Unsaved review changes';}
function canLeave(){return !s.dirty||confirm('Discard the unsaved review draft?');}
function versionName(v){return (v.dataset?.name||v.dataset?.datasetId||v.dataset?.snapshot||'Imported edition')+' · '+v.row_count+' rows · '+short(v.version_id);}
async function loadVersions(more=false){const page=await api('/api/versions'+(more&&s.versionNext?'?before='+s.versionNext:''));s.versions=more?[...s.versions,...page.versions]:page.versions;s.versionNext=page.next_before;const old=$('version').value;const select=$('version');select.replaceChildren();for(const v of s.versions){const o=node('option',versionName(v));o.value=v.version_id;select.append(o);}if(s.versions.some(v=>v.version_id===old))select.value=old;$('more-versions').hidden=!s.versionNext;renderVersion();}
function renderVersion(){const v=s.versions.find(v=>v.version_id===$('version').value);$('version-info').replaceChildren();$('column-options').replaceChildren();if(!v){$('version-info').textContent='Import a retained dataset or API response in the analysis workspace first.';return;}fact($('version-info'),'Rows',v.row_count);fact($('version-info'),'Columns',v.column_types.length);fact($('version-info'),'Version',v.version_id);for(const c of v.column_types){const label=node('label'),input=node('input');input.type='checkbox';input.checked=true;input.value=c.column;label.append(input,document.createTextNode(c.column));$('column-options').append(label);}}
async function loadHistory(more=false){const page=await api('/api/profiles'+(more&&s.historyNext?'?before='+s.historyNext:''));s.profiles=more?[...s.profiles,...page.profiles]:page.profiles;s.historyNext=page.next_before;$('more-history').hidden=!s.historyNext;renderHistory();}
function renderHistory(){const box=$('history');box.replaceChildren();for(const p of s.profiles){const item=node('div');item.className='history-item';const b=action(short(p.version_id)+' · '+p.status,()=>openProfile(p.id));b.disabled=p.status!=='COMPLETE';item.append(b,node('small',p.created_at),node('small',short(p.id)+(p.error?' · '+p.error:'')));box.append(item);}if(!s.profiles.length)box.append(node('p','No profiles yet.'));for(const id of ['before','after']){const old=$(id).value;$(id).replaceChildren(node('option','Select a complete profile'));$(id).firstChild.value='';for(const p of s.profiles.filter(p=>p.status==='COMPLETE')){const o=node('option',short(p.version_id)+' · '+p.created_at);o.value=p.id;$(id).append(o);}if(s.profiles.some(p=>p.id===old))$(id).value=old;}s.active=s.profiles.find(p=>p.status==='RUNNING')?.id||null;controls();}
async function refresh(){if(!s.workspaceId){const state=await api('/api/state');s.workspaceId=state.workspace_id;loadPending();}await loadVersions();await loadHistory();await restorePendingDraft();if(s.active)poll();renderPending();message('Original customer workspace ready.');}
function metric(label,value){const d=node('div');d.className='metric';d.append(node('strong',value),node('span',label));$('overview').append(d);}
async function openProfile(id){if(!canLeave())return;s.document=await api('/api/profiles/'+id);s.column=null;s.notes={...(s.document.review?.column_notes||{})};s.dirty=false;$('draft-state').textContent='';$('column-detail').hidden=true;$('profile-panel').hidden=false;const p=s.document.profile;$('profile-title').textContent=(p.source.dataset?.name||'Retained edition')+' · '+short(p.source.version_id);$('overview').replaceChildren();metric('Rows inspected',p.row_count);metric('Columns',p.columns.length);metric('Columns with nulls',p.columns.filter(c=>c.null_rows>0).length);metric('Mixed native types',p.columns.filter(c=>Object.values(c.storage_classes).filter(v=>v>0).length>1).length);$('source').textContent=JSON.stringify({source:p.source,scope:p.scope,profile_sha256:p.sha256},null,2);$('decision').value=s.document.review?.decision||'unclassified';$('note').value=s.document.review?.note||'';$('review-version').textContent=s.document.review?'Saved revision '+s.document.review.revision+' · '+s.document.review.saved_at:'No saved review. Classification is an analyst note, not an acquisition or runtime control.';$('after').value=id;renderSummary();message('Opened complete profile '+short(id)+'.');}
function renderSummary(){if(!s.document)return;const term=$('column-filter').value.toLowerCase();$('summary').replaceChildren();for(const c of s.document.profile.columns.filter(c=>(c.column+' '+c.source_field).toLowerCase().includes(term))){const tr=node('tr');cell(tr,c.column);cell(tr,c.null_rows+' / '+c.rows);cell(tr,c.empty_text_rows);cell(tr,c.distinct_nonnull);cell(tr,c.duplicate_nonnull_rows);cell(tr,Object.entries(c.storage_classes).filter(([,v])=>v).map(([k,v])=>k+': '+v).join(', ')||'Empty edition');cell(tr).append(action('Inspect',()=>openColumn(c.column)));$('summary').append(tr);}}
function keepColumnNote(){if(s.column){s.notes[s.column]=$('column-note').value;}}
async function openColumn(name){keepColumnNote();s.column=name;const c=s.document.profile.columns.find(c=>c.column===name);$('column-detail').hidden=false;$('column-title').textContent=name;$('column-facts').replaceChildren();fact($('column-facts'),'Original field',c.source_field);fact($('column-facts'),'Original JSON types',c.original_json_types.join(', ')||'No rows');fact($('column-facts'),'Numeric minimum',text(c.numeric_min));fact($('column-facts'),'Numeric maximum',text(c.numeric_max));fact($('column-facts'),'Text minimum',text(c.text_min));fact($('column-facts'),'Text maximum',text(c.text_max));fact($('column-facts'),'Text length in characters',c.text_characters_min===null?'No text':c.text_characters_min+' → '+c.text_characters_max);fact($('column-facts'),'Whitespace-only rows',c.whitespace_text_rows);$('values').replaceChildren();for(const v of c.top_values){const tr=node('tr');const td=cell(tr,text(v.value));td.title=v.value.sha256||'';cell(tr,v.value.type);cell(tr,v.rows);$('values').append(tr);}$('values-scope').textContent=c.top_values_complete?'Every distinct native value is shown.':'Showing the '+c.top_values.length+' most frequent values out of '+c.distinct_including_null+'. Counts and ranges include every group.';$('column-note').value=s.notes[name]||'';const q=await api('/api/profiles/'+s.document.profile.id+'/frequency?column='+encodeURIComponent(name));$('frequency-sql').textContent=q.sql;}
async function poll(){const id=s.active;if(!id)return;try{const job=await api('/api/jobs/'+id),p=await api('/api/profiles/'+id+'/progress');$('progress').textContent=p.progress?'Column '+(p.progress.columns_complete||0)+' / '+(p.progress.columns_total||'?')+' · '+(p.progress.current_column||'Preparing'):job.status;if(job.status!=='RUNNING'){s.active=null;await loadHistory();$('progress').textContent=job.status;if(job.status==='COMPLETE')await openProfile(id);else message('Profile '+job.status+(job.error?': '+job.error:''),job.status==='FAILED');return;}}catch(e){message(e.message,true);return;}setTimeout(()=>{if(s.active===id)poll();},1200);}
async function download(path,name){const r=await fetch(path,{headers:{'X-Analysis-Capability':capability},cache:'no-store'});if(!r.ok){const e=await r.json();throw Error(e.error||'Export failed');}const blob=await r.blob(),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function saveJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}));const a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
for(const id of ['before','after'])$(id).addEventListener('change',controls);
$('refresh').addEventListener('click',()=>act(refresh));$('version').addEventListener('change',renderVersion);$('more-versions').addEventListener('click',()=>act(()=>loadVersions(true)));$('more-history').addEventListener('click',()=>act(()=>loadHistory(true)));$('all-columns').addEventListener('click',()=>{for(const c of $('column-options').querySelectorAll('input'))c.checked=true;});$('no-columns').addEventListener('click',()=>{for(const c of $('column-options').querySelectorAll('input'))c.checked=false;});
$('run').addEventListener('click',()=>act(async()=>{if(!canLeave())return;const all=[...$('column-options').querySelectorAll('input')],columns=all.filter(c=>c.checked).map(c=>c.value);if(!columns.length)throw Error('Select at least one column.');const spec={version_id:$('version').value,columns:columns.length===all.length?null:columns,top_values:Number($('top-values').value),timeout:Number($('timeout').value)};if(s.pending.run){const {id,...original}=s.pending.run.body;if(JSON.stringify(original)!==JSON.stringify(spec))throw Error('Resolve the retained profile request before starting a different selection.');}else storePending({...s.pending,run:{body:{id:newRequestId(),...spec}}});await submitPendingRun();}));
$('cancel').addEventListener('click',async()=>{try{if(s.active){const r=await api('/api/profiles/'+s.active+'/cancel',{});message(r.requested?'Cancellation requested for this profile.':'Profile is already '+r.status);}}catch(e){message(e.message,true);}});
$('column-filter').addEventListener('input',renderSummary);$('note').addEventListener('input',markDirty);$('decision').addEventListener('change',markDirty);$('column-note').addEventListener('input',markDirty);$('keep-column-note').addEventListener('click',()=>{keepColumnNote();markDirty();message('Column note retained in the review draft. Save review to persist it.');});
$('save-review').addEventListener('click',()=>act(async()=>{keepColumnNote();const p=s.document.profile,spec={profile_sha256:p.sha256,decision:$('decision').value,note:$('note').value,column_notes:JSON.parse(JSON.stringify(s.notes))};if(s.pending.review){const original=s.pending.review.body;if(s.pending.review.profile_id!==p.id||original.profile_sha256!==spec.profile_sha256||original.decision!==spec.decision||original.note!==spec.note||JSON.stringify(original.column_notes)!==JSON.stringify(spec.column_notes))throw Error('Resolve the retained review save before replacing its edited notes.');}else storePending({...s.pending,review:{profile_id:p.id,body:{id:newRequestId(),expected_revision:s.document.review?.revision||0,...spec}}});await submitPendingReview();}));
$('save-frequency').addEventListener('click',()=>act(async()=>{const q=await api('/api/profiles/'+s.document.profile.id+'/frequency-query',{column:s.column,name:$('query-name').value.trim(),expected_revision:0});message('Saved '+q.name+' revision '+q.revision+'. Open it in the analysis workspace for full SQL export.');}));
for(const format of ['json','html'])$('download-'+format).addEventListener('click',()=>act(async()=>{if(s.dirty)throw Error('Save or discard review changes before exporting.');await download('/api/profiles/'+s.document.profile.id+'/export?format='+format+'&expected_sha256='+s.document.sha256,'data-profile-'+short(s.document.profile.id)+'.'+format);}));
$('compare').addEventListener('click',()=>act(async()=>{s.comparison=await api('/api/profile-compare?before='+$('before').value+'&after='+$('after').value);const c=s.comparison;$('comparison').hidden=false;$('comparison-summary').textContent='Imported row change: '+(c.row_delta>0?'+':'')+c.row_delta+'. '+c.columns.filter(v=>v.status!=='unchanged').length+' of '+c.columns.length+' columns differ.';$('comparison-rows').replaceChildren();const delta=v=>v==null?'—':(v>0?'+':'')+v;for(const col of c.columns){const tr=node('tr');cell(tr,col.column);cell(tr,col.status);cell(tr,delta(col.deltas?.null_rows));cell(tr,delta(col.deltas?.distinct_nonnull));cell(tr,delta(col.deltas?.duplicate_nonnull_rows));cell(tr,text(col.before?.numeric_min)+' … '+text(col.before?.numeric_max)+' → '+text(col.after?.numeric_min)+' … '+text(col.after?.numeric_max));$('comparison-rows').append(tr);}$('comparison-source').textContent=JSON.stringify({before:c.before_source,after:c.after_source,basis:c.basis},null,2);message('Compared the complete retained profiles.');}));
$('comparison-json').addEventListener('click',()=>saveJSON(s.comparison,'data-profile-comparison.json'));
window.addEventListener('beforeunload',e=>{if(s.dirty||s.pending.run||s.pending.review||s.pendingInvalid){e.preventDefault();e.returnValue='';}});
$('retry-run').addEventListener('click',()=>act(submitPendingRun));
$('retry-review').addEventListener('click',()=>act(submitPendingReview));
$('forget-pending').addEventListener('click',()=>act(async()=>{if(!confirm('Forget only these retained browser requests? A run or review may already have been accepted. Its saved workspace history will remain.'))return;storePending({run:null,review:null});message('Local pending requests forgotten explicitly. Original saved operations remain in the workspace.');}));
act(refresh);
'''

"""Packaged report editor, retained publications and downloads for the customer UI."""

HTML = r'''
<section id="tab-reports" hidden>
<section class="panel"><div class="section-head"><div><h2>Customer reports</h2><p>Compose saved analyses into a complete report. Every section reads the same reviewed data selection.</p></div><button id="report-new">New report</button></div>
<div class="form-row"><label>Saved report<select id="report-saved"><option value="">Unsaved report</option></select></label><label>Definition revision<select id="report-revision"><option value="">—</option></select></label><label>Save as<input id="report-name" autocomplete="off" spellcheck="false" placeholder="inventory_review"></label></div>
<p id="report-editor-state" class="muted"></p><label for="report-title">Report title</label><input id="report-title" maxlength="300" placeholder="Inventory review"><label for="report-introduction">Introduction</label><textarea id="report-introduction" rows="3" maxlength="16000" placeholder="Purpose, reporting scope and the decisions this report supports."></textarea>
<div class="section-head"><h3>Ordered report sections</h3><button id="report-add-section">Add saved analysis</button></div><p id="report-query-help" class="hint">Save SQL analyses in Analysis first. Each report section retains its chosen query revision and effective parameters.</p><div id="report-sections"></div>
<div class="toolbar"><button id="report-save">Save report definition</button><button id="report-run" class="primary">Run saved report</button><button id="report-review-views">Use current data selection</button></div><p id="report-review-state" class="muted"></p><details><summary>Reviewed current views</summary><pre id="report-reviewed-views"></pre></details>
</section>
<section id="report-result" class="panel" hidden><div class="section-head"><div><h2 id="report-result-title">Retained report</h2><p id="report-result-info"></p></div><div class="toolbar"><button id="report-result-refresh">Refresh report state</button><label>Report section<select id="report-result-section"></select></label></div></div>
<p id="report-result-introduction"></p><h3 id="report-section-title"></h3><p id="report-section-note"></p><div class="table-scroll"><table id="report-result-table"><thead></thead><tbody></tbody></table></div><div class="section-head"><p id="report-result-page" class="muted"></p><div class="toolbar"><button id="report-result-prev">Previous rows</button><button id="report-result-next">Next rows</button></div></div>
