JS = r'''
'use strict';
const $=id=>document.getElementById(id);
const initial=location.hash.slice(1);
if(initial){sessionStorage.setItem('sf-analysis-capability',initial);history.replaceState(null,'',location.pathname);}
const capability=sessionStorage.getItem('sf-analysis-capability')||'';
const s={data:null,busy:false,active:null,focusJob:null,pending:null,version:null,versionPage:null,versionBefore:null,versionHistory:[],result:null,backup:null,editor:null,editorBase:'',draftLoaded:false,queryLoad:0,resultLoad:0,poll:null,changeCandidate:null,changePlan:null,changePlanLoad:0,change:null,changeLoad:0,changePages:[],changeHistory:null,changeHistoryBefore:null,changeHistoryPages:[],changeDownload:null,responseRecovery:null};
const scalar=v=>v===null||v===undefined?'—':String(v);
const short=v=>typeof v==='string'&&v.length>20?v.slice(0,12)+'…':scalar(v);
const stamp=v=>v?new Date(v).toLocaleString():'—';
const quote=v=>'"'+v.replaceAll('"','""')+'"';
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn){const n=node('button',text);n.addEventListener('click',()=>act(fn));return n;}
function cell(row,text,cls){const n=node('td',text,cls);row.append(n);return n;}
function fact(parent,label,value){const div=node('div');div.append(node('b',label),document.createTextNode(scalar(value)));parent.append(div);}
function empty(body,count,text){const row=node('tr'),td=cell(row,text);td.colSpan=count;body.append(row);}
function tab(name){for(const n of ['data','research','responses','changes','analysis','reports','workbooks','exports','archives','activity'])$('tab-'+n).hidden=n!==name;for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===name));}
async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Analysis-Capability':capability,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const data=await response.json();if(!response.ok){const error=Error(data.error||'Request failed');error.status=response.status;throw error;}return data;}
function controls(){const unavailable=s.busy||!s.data;for(const id of ['backup','import','activate','manifest','dictionary','use-table','save-query','run-query','new-query','saved-query','query-revision','source'])$(id).disabled=unavailable;for(const id of ['import','run-query'])$(id).disabled||=Boolean(s.active);$('refresh').disabled=s.busy;$('import').disabled||=!s.data?.can_import||!$('source').value;$('activate').disabled||=!s.version;$('manifest').disabled||=!s.version;$('dictionary').disabled||=!s.version?.semantics;$('use-table').disabled||=!s.version;$('versions-prev').disabled=unavailable||!s.versionHistory.length;$('versions-next').disabled=unavailable||!s.versionPage?.next_before;for(const id of ['result-prev','result-next','export-json','export-csv'])$(id).disabled=unavailable||!s.result;$('result-prev').disabled||=!s.result?.result?.offset;$('result-next').disabled||=s.result?.result?.next_offset==null;$('backup-download').disabled=unavailable;$('response-resume-job').disabled=unavailable||!!s.active||s.responseRecovery?.status!=='INTERRUPTED';for(const id of ['query-name','sql','parameters','max-rows','mapping','view-name'])$(id).disabled=s.busy;changeControls();window.customerReports?.controls();window.responseTables?.controls();window.customerExports?.controls();window.customerWorkbooks?.controls();window.workspaceArchives?.controls();window.researchIntake?.controls();}
async function act(fn){if(s.busy)return;s.busy=true;controls();try{await fn();}catch(e){message(e.message,true);}finally{s.busy=false;controls();}}
function editorValue(){return {name:$('query-name').value.trim(),sql:$('sql').value,parameters_text:$('parameters').value,max_rows:Number($('max-rows').value)};}
function editorKey(){return JSON.stringify(editorValue());}
function dirty(){return editorKey()!==s.editorBase;}
function storeDraft(){if(!s.data)return;try{localStorage.setItem('sf-analysis-draft:'+s.data.workspace_id,JSON.stringify({value:editorValue(),editor:s.editor,base:s.editorBase}));}catch{}editorLabel();}
function editorLabel(){const name=$('query-name').value.trim(),same=s.editor&&name===s.editor.name;const detail=same?'Loaded revision '+s.editor.revision+'; next save uses current revision '+s.editor.head_revision+'.':'New saved analysis.';$('editor-state').textContent=detail+(dirty()?' Unsaved changes.':'');}
function setEditor(value,record=null){$('query-name').value=value.name||'';$('sql').value=value.sql||'';$('parameters').value=value.parameters_text||'[]';$('max-rows').value=value.max_rows||1000;s.editor=record;s.editorBase=editorKey();$('saved-query').value=record?.name||'';const select=$('query-revision');select.replaceChildren();if(record){for(const h of record.history||[{revision:record.revision}]){const o=node('option','Revision '+h.revision);o.value=h.revision;select.append(o);}select.value=String(record.revision);}else select.append(node('option','—'));storeDraft();}
function confirmEditor(){return !dirty()||confirm('Discard the unsaved analysis changes?');}
function renderSources(){const old=$('source').value,select=$('source');select.replaceChildren();for(const source of s.data.sources.filter(v=>v.kind!=='response')){const option=node('option',source.name+' · '+source.native_status);option.value=source.name;select.append(option);}if(!s.data.sources.some(v=>v.kind!=='response')){const option=node('option','No registered source');option.value='';select.append(option);}if(s.data.sources.some(v=>v.kind!=='response'&&v.name===old))select.value=old;sourceInfo();}
function sourceInfo(){const source=s.data?.sources.find(v=>v.name===$('source').value),box=$('source-info');box.replaceChildren();if(source){fact(box,'Native status',source.native_status);fact(box,'Acquired rows',source.rows);fact(box,'Snapshot',source.snapshot);fact(box,'Source revision',source.revision);}$('source-help').textContent=s.data?.can_import?'Imports use the original local acquisition and data-room files.':'Start with --checkout to enable original data-room imports. Retained analysis works without it.';controls();}
function renderViews(){const body=$('views');body.replaceChildren();for(const view of s.data.views){const row=node('tr');cell(row,view.name,'code');cell(row,view.revision);const identity=cell(row,short(view.version_id),'code');identity.title=view.version_id;cell(row).append(button('Query',()=>useSql('SELECT * FROM '+quote(view.name)+' LIMIT 100')));body.append(row);}if(!s.data.views.length)empty(body,4,'Select an imported version below to create a current view.');$('query-views').textContent=JSON.stringify(s.data.views,null,2);activationInfo();}
function activationInfo(){const name=$('view-name').value.trim();const view=s.data?.views.find(v=>v.name.toLowerCase()===name.toLowerCase());$('activation-info').textContent=view?'Current revision '+view.revision+' selects '+short(view.version_id)+'. This action will use that reviewed revision.':'This name will create a new SQL view at revision 1.';}
function renderQueries(){const select=$('saved-query'),old=select.value;select.replaceChildren();const blank=node('option','Unsaved analysis');blank.value='';select.append(blank);for(const query of s.data.queries){const option=node('option',query.name+' · revision '+query.revision);option.value=query.name;select.append(option);}if(s.data.queries.some(v=>v.name===s.editor?.name))select.value=s.editor.name;else if(s.data.queries.some(v=>v.name===old))select.value=old;}
function renderJobs(){const body=$('jobs');body.replaceChildren();for(const job of s.data.jobs){const row=node('tr');cell(row,stamp(job.created_at));cell(row,job.kind);cell(row,job.status+(job.error?' · '+job.error:''));cell(row).append(button('Open',()=>openJob(job.id)));body.append(row);}if(!s.data.jobs.length)empty(body,4,'No workspace activity yet.');}
async function loadVersions(before=s.versionBefore){const data=await api('/api/versions'+(before?'?before='+before:''));s.versionPage=data;s.versionBefore=before;renderVersions();}
function renderVersions(){const body=$('versions');body.replaceChildren();for(const version of s.versionPage?.versions||[]){const row=node('tr');row.classList.toggle('selected',version.version_id===s.version?.version_id);cell(row,stamp(version.created_at));cell(row,(version.dataset.name||version.dataset.datasetId||version.dataset.id||'Dataset')+' / '+short(version.dataset.snapshot||version.dataset.response?.original?.sourceSha256));cell(row,version.row_count);const identity=cell(row,short(version.version_id),'code');identity.title=version.version_id;cell(row).append(button('Select',()=>selectVersion(version.version_id)));body.append(row);}if(!s.versionPage?.versions.length)empty(body,5,'Import a completed delivery to start using its rows.');$('versions-page').textContent='History page '+(s.versionHistory.length+1)+' · newest first';controls();}
async function selectVersion(id){const version=await api('/api/version/'+encodeURIComponent(id));s.version=version;const box=$('version-info');box.replaceChildren();fact(box,'Version',version.version_id);fact(box,'Rows',version.row_count);fact(box,'SQL table',version.table);fact(box,'Snapshot',version.dataset.snapshot);if(version.dataset.kind==='retained-response'){fact(box,'Source kind',version.dataset.response.original.nativeKind);fact(box,'Original response SHA-256',version.dataset.response.original.sourceSha256);fact(box,'Response complete',version.dataset.completion.transportComplete);fact(box,'Provider declared truncation',version.dataset.completion.providerDeclaredTruncated);fact(box,'Incomplete scope acknowledged',version.dataset.completion.incompleteAcknowledged);}fact(box,'Manifest SHA-256',version.manifestSha256);fact(box,'Native payment status',version.originalPaymentStatus);const body=$('columns');body.replaceChildren();const meanings=new Map((version.semantic_dictionary?.columns||[]).map(c=>[c.name,c]));for(const column of version.column_types){const row=node('tr');cell(row,column.source,'code');cell(row,column.column,'code');cell(row,column.json_types.join(', '));const definition=meanings.get(column.source)?.projectedDefinition;const meaning=cell(row);if(definition)meaning.append(node('pre',JSON.stringify(definition,null,2),'semantic-definition'));else meaning.textContent='—';body.append(row);}renderSemantics(version);$('version-detail').hidden=false;renderVersions();activationInfo();}
function renderSemantics(version){
 const box=$('semantic-info'),dictionary=version.semantic_dictionary,metadata=version.semantics;box.replaceChildren();$('dictionary').hidden=!dictionary;
 if(!dictionary){box.append(node('p','This imported edition has no reviewed source dictionary.','muted'));return;}
