 const detail=node('details'),summary=node('summary','Identity, units, code lists and source attribution');detail.append(summary,node('pre',JSON.stringify({source:dictionary.source,primaryKey:dictionary.primaryKey,aboutUrl:dictionary.aboutUrl,virtualColumns:dictionary.virtualColumns,issues:dictionary.issues},null,2)));box.append(detail);
