async function refresh(){const data=await api('/api/state');s.data=data;$('connection').textContent='Connected';$('database-path').textContent=data.database;renderSources();renderViews();renderQueries();renderJobs();await loadVersions();await refreshChanges();await window.customerReports?.refresh();await window.responseTables?.refresh();await window.customerExports?.refresh();await window.customerWorkbooks?.refresh();await window.workspaceArchives?.refresh();await window.researchIntake?.refresh();if(!s.draftLoaded){s.draftLoaded=true;let draft;try{draft=JSON.parse(localStorage.getItem('sf-analysis-draft:'+data.workspace_id));}catch{}if(draft?.value){setEditor(draft.value,draft.editor);s.editorBase=draft.base;storeDraft();}else setEditor({sql:'SELECT * FROM inventory LIMIT 100',parameters_text:'[]',max_rows:1000});}const running=data.jobs.find(j=>j.status==='RUNNING');if(running&&!s.active){s.active=running.id;schedulePoll();}if(!running&&s.active){const job=await api('/api/jobs/'+s.active);await completed(job,false);}controls();}
async function useSql(sql){if(!confirmEditor())return;setEditor({sql,parameters_text:'[]',max_rows:1000});tab('analysis');$('sql').focus();}
async function loadQuery(name,revision){if(!name)return;if(!confirmEditor()){$('saved-query').value=s.editor?.name||'';$('query-revision').value=s.editor?.revision||'';return;}const sequence=++s.queryLoad;const value=await api('/api/queries/'+encodeURIComponent(name)+(revision?'?revision='+revision:''));if(sequence!==s.queryLoad)return;setEditor(value,value);message('Loaded '+name+' revision '+value.revision+'.');}
function id(){return crypto.randomUUID().replaceAll('-','');}
async function start(kind,spec){const key=JSON.stringify({kind,spec});if(s.pending?.key!==key)s.pending={key,request:{id:id(),...spec}};const job=await api('/api/start/'+kind,s.pending.request);s.pending=null;s.focusJob=job.id;s.active=job.status==='RUNNING'?job.id:null;message(({query:'Running analysis on the reviewed data selection.',import:'Importing the original completed delivery.','response-preview':'Checking every mapped response record.','response-import':'Importing the reviewed response projection.',compare:'Comparing every acquired row and retaining complete differences.','change-export':'Writing the complete retained comparison export.',report:'Running all report sections on the reviewed data snapshot.','report-export':'Writing the complete reviewed customer report.',workbook:'Writing the complete saved workbook and source handoff.','query-export':'Writing every row returned by the reviewed query.',backup:'Creating a consistent database backup.','workspace-export':'Saving the complete workspace and its original outputs.'})[kind]);window.customerExports?.progress(job);window.customerWorkbooks?.progress(job);window.workspaceArchives?.progress(job);window.researchIntake?.progress(job);if(job.status==='RUNNING')schedulePoll();else await completed(job);controls();}
function schedulePoll(){clearTimeout(s.poll);s.poll=setTimeout(async()=>{const active=s.active;if(!active)return;try{const job=await api('/api/jobs/'+active);if(active!==s.active)return;if(job.status==='RUNNING'){window.customerExports?.progress(job);window.customerWorkbooks?.progress(job);window.workspaceArchives?.progress(job);window.researchIntake?.progress(job);schedulePoll();return;}await completed(job);}catch(e){message(e.message+' Refresh to reconnect to the retained action.',true);}},700);}
async function completed(job,refreshAfter=true){if(job.status==='RUNNING')return;if(s.active===job.id)s.active=null;clearTimeout(s.poll);window.customerExports?.settled(job);window.customerWorkbooks?.settled(job);window.workspaceArchives?.settled(job);window.researchIntake?.settled(job);if(job.status==='CANCELLED'&&job.kind==='query-export'){message('Export cancelled. Reopen its retained query review to start another export.');}else if(job.status!=='COMPLETE'){message(job.status+': '+(job.error||'The action did not finish.')+' Previous imported versions and query results remain available.',true);}else if(s.focusJob===job.id){if(job.kind==='query'){s.result=job;renderResult();tab('analysis');message('Analysis completed and retained.');await window.customerExports?.queryReady(job);}else if(job.kind==='response-preview'){await window.responseTables.open(job);message('Every selected response record was checked. Review the projection and its source scope.');}else if(job.kind==='import'||job.kind==='response-import'){s.versionBefore=null;s.versionHistory=[];await selectVersion(job.result.version.version_id);tab('data');message(job.result.version.import_status+': '+job.result.version.row_count+' original rows. Select the version for a current SQL view when ready.');}else if(job.kind==='compare'){await openComparison(job.id);message('Complete comparison retained. Review its acquisition scope and changes before selecting.');}else if(job.kind==='report'){await window.customerReports.open(job.id);message('Complete report retained. Review its sections and publish an edition when ready.');}else if(job.kind==='report-export'){await window.customerReports.exportReady(job);}else if(job.kind==='workbook'){await window.customerWorkbooks.open(job.id,job);}else if(job.kind==='query-export'){await window.customerExports.open(job.id,job);message('Complete query export retained. Open its manifest or download the selected files.');}else if(job.kind==='research-capture'){await window.researchIntake.open(job);message('Original Research edition retained as an Analysis source.');}else if(job.kind==='workspace-export'){await window.workspaceArchives.open(job.id,job);message('Complete workspace backup is ready. Download its ZIP and manifest.');}else{showActivity(job);tab('activity');message(job.kind==='change-export'?'Complete comparison export retained. Download it below.':'Database backup created.');}}if(refreshAfter)await refresh();controls();}
function renderResult(){const job=s.result,result=job?.result;if(!result)return;$('query-result').hidden=false;$('result-info').textContent=stamp(job.finished_at)+' · '+result.total_rows+' retained rows · '+job.id;$('truncation').hidden=!result.truncated;$('truncation').textContent='This result reached its configured row or byte limit. The saved export contains the retained prefix.';const table=$('result-table');table.tHead.replaceChildren();table.tBodies[0].replaceChildren();const head=node('tr');for(const column of result.columns)head.append(node('th',column));table.tHead.append(head);for(const values of result.rows){const row=node('tr');for(const value of values){const td=cell(row,value.type==='null'?'NULL':value.text);td.classList.toggle('null',value.type==='null');td.classList.toggle('number',['integer','number'].includes(value.type));td.title=value.type;}table.tBodies[0].append(row);}if(!result.rows.length)empty(table.tBodies[0],Math.max(result.columns.length,1),'No rows in this result.');$('result-page').textContent=result.total_rows?'Rows '+(result.offset+1)+'–'+(result.offset+result.rows.length)+' of '+result.total_rows:'0 rows';$('result-binding').textContent=JSON.stringify({sql:job.request.sql,parameters_text:job.request.parameters_text,views:result.views,read_tables:result.read_tables,source_versions:result.source_versions,result_sha256:result.result_sha256},null,2);controls();}
async function resultPage(offset){if(!s.result)return;const current=s.result.id,sequence=++s.resultLoad;const next=await api('/api/jobs/'+current+'?offset='+offset);if(sequence!==s.resultLoad||s.result?.id!==current)return;s.result=next;renderResult();}
function showActivity(job){$('activity-detail').hidden=false;$('activity-title').textContent=job.kind+' · '+job.status;$('activity-info').textContent=JSON.stringify(job,null,2);s.backup=job.kind==='backup'&&job.status==='COMPLETE'?job:null;$('backup-download').hidden=!s.backup?.result.downloadable;s.changeDownload=job.kind==='change-export'&&job.status==='COMPLETE'?job:null;$('change-download').hidden=!s.changeDownload;s.responseRecovery=['response-preview','response-import'].includes(job.kind)?job:null;const resumable=s.responseRecovery?.status==='INTERRUPTED';$('response-resume-job').hidden=!resumable;$('response-resume-note').hidden=!resumable;controls();}
async function openJob(jobId){s.focusJob=jobId;++s.resultLoad;const job=await api('/api/jobs/'+jobId);if(['response-preview','response-import'].includes(job.kind)&&job.status!=='RUNNING'&&s.active===job.id){s.active=null;clearTimeout(s.poll);}if(job.kind==='query'&&job.status==='COMPLETE'){s.result=job;renderResult();tab('analysis');}else if(job.kind==='response-preview'&&job.status==='COMPLETE'){await window.responseTables.open(job);}else if(job.kind==='compare'&&job.status==='COMPLETE'){await openComparison(job.id);}else if(job.kind==='report'&&job.status==='COMPLETE'){await window.customerReports.open(job.id);}else if(job.kind==='report-export'&&job.status==='COMPLETE'){await window.customerReports.exportReady(job);}else if(job.kind==='workbook'){await window.customerWorkbooks.open(job.id,job);}else if(job.kind==='query-export'){await window.customerExports.open(job.id,job);}else if(job.kind==='research-capture'){await window.researchIntake.open(job);}else if(job.kind==='workspace-export'){await window.workspaceArchives.open(job.id,job);}else{showActivity(job);tab('activity');}if(job.status==='RUNNING'){s.active=job.id;schedulePoll();}}
async function download(path,fallback){const response=await fetch(path,{headers:{'X-Analysis-Capability':capability},cache:'no-store'});if(!response.ok){const error=await response.json();throw Error(error.error||'Download failed');}const blob=await response.blob(),url=URL.createObjectURL(blob);const anchor=node('a');anchor.href=url;anchor.download=response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||fallback;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function changeControls(){
 const unavailable=s.busy||!s.data,plan=s.changePlan,report=s.change?.report,current=report&&s.data?.views.find(v=>v.name.toLowerCase()===report.reviewed_view.name.toLowerCase());
 for(const name of ['review-version','change-view','change-plan-refresh','change-run','change-kind','change-prev','change-next','change-history-prev','change-history-next','change-select','change-query','change-export-json','change-export-csv','change-base-manifest','change-candidate-manifest','change-download'])$(name).disabled=unavailable;
 $('review-version').disabled||=!s.version||!s.data?.views.length;
 $('change-view').disabled||=!s.changeCandidate;
 $('change-plan-refresh').disabled||=!s.changeCandidate||!$('change-view').value;
 const planned=plan&&s.data?.views.some(v=>v.name.toLowerCase()===plan.view.name.toLowerCase()&&v.revision===plan.view.revision&&v.version_id===plan.view.version_id);
 $('change-run').disabled||=!!s.active||!planned||!document.querySelector('#change-keys input:checked');
 for(const input of document.querySelectorAll('#change-keys input'))input.disabled=unavailable;
 for(const name of ['change-kind','change-query','change-export-json','change-export-csv','change-base-manifest','change-candidate-manifest'])$(name).disabled||=!report;
 for(const name of ['change-export-json','change-export-csv'])$(name).disabled||=!!s.active;
 $('change-prev').disabled||=!s.changePages.length;
 $('change-next').disabled||=s.change?.next_after==null;
 $('change-history-prev').disabled||=!s.changeHistoryPages.length;
 $('change-history-next').disabled||=!s.changeHistory?.next_before;
 $('change-select').disabled||=!!s.active||!report||!!s.change?.selection||current?.revision!==report?.reviewed_view.revision||current?.version_id!==report?.reviewed_view.version_id;
 $('change-query').disabled||=!current;
 $('change-note').disabled=unavailable||!report||!!s.change?.selection;
 $('change-download').disabled||=!s.changeDownload;
 if(report)selectionInfo();
}
function versionFacts(box,label,version){fact(box,label+' dataset',version.dataset.name||version.dataset.datasetId||version.dataset.id||'Dataset');fact(box,label+' version',version.version_id);fact(box,label+' rows',version.row_count);fact(box,label+' snapshot',version.dataset.snapshot);if(version.semantics){fact(box,label+' meaning',version.semantics.semantic_sha256);fact(box,label+' definitions',version.semantics.definition_sha256);}}
async function refreshChanges(){
 const select=$('change-view'),old=select.value;select.replaceChildren();
 for(const view of s.data.views){const option=node('option',view.name+' · revision '+view.revision);option.value=view.name;select.append(option);}
 if(!s.data.views.length){const option=node('option','No current view');option.value='';select.append(option);}
 if(s.data.views.some(v=>v.name===old))select.value=old;
 await loadChangeHistory(s.changeHistoryBefore);renderChangePlan();
}
async function beginComparison(){
 if(!s.version)throw Error('Select an imported candidate in Data.');
 s.changeCandidate=s.version;s.changePlan=null;++s.changePlanLoad;
 const box=$('change-candidate');box.replaceChildren();versionFacts(box,'Candidate',s.changeCandidate);
 tab('changes');await loadChangePlan();
}
async function loadChangePlan(){
 const candidate=s.changeCandidate,view=s.data.views.find(v=>v.name===$('change-view').value),sequence=++s.changePlanLoad;
 if(!candidate||!view){s.changePlan=null;renderChangePlan();return;}
 const baseline=await api('/api/version/'+view.version_id);
 if(sequence!==s.changePlanLoad||candidate.version_id!==s.changeCandidate?.version_id)return;
 const before=new Set(baseline.column_types.map(c=>c.column)),columns=candidate.column_types.map(c=>c.column).filter(c=>before.has(c));
 s.changePlan={view:{...view},baseline,candidate,columns};
 const options=$('change-keys');options.replaceChildren();
 const preferred=columns.find(c=>['id','sku','record_id'].includes(c.toLowerCase()));
 for(const name of columns){const label=node('label'),input=document.createElement('input');input.type='checkbox';input.value=name;input.checked=name===preferred;input.addEventListener('change',changeControls);label.append(input,document.createTextNode(name));options.append(label);}
 renderChangePlan();changeControls();
}
function renderChangePlan(){
 const box=$('change-plan');box.replaceChildren();const plan=s.changePlan;
 if(!plan){box.textContent='Load a current view after choosing an imported candidate.';return;}
 fact(box,'Reviewed view',plan.view.name+' · revision '+plan.view.revision);versionFacts(box,'Baseline',plan.baseline);
 const first=plan.baseline.semantics,second=plan.candidate.semantics;
 if(first||second){
  fact(box,'Source definitions',first?.definition_sha256===second?.definition_sha256?'Same reviewed meaning':'Review the changed source dictionary');
  fact(box,'Capture identity',first?.capture_manifest_sha256===second?.capture_manifest_sha256?'Same retained capture':'Different retained captures');
  fact(box,'SQL mapping',JSON.stringify(plan.baseline.columns)===JSON.stringify(plan.candidate.columns)?'Same field mapping':'Changed field mapping');
  box.append(button('Download meaning comparison',()=>download('/api/semantic-compare?before='+encodeURIComponent(plan.baseline.version_id)+'&after='+encodeURIComponent(plan.candidate.version_id),'source-meaning-comparison.json')));
 }
 const current=s.data?.views.find(v=>v.name.toLowerCase()===plan.view.name.toLowerCase());
 if(current?.revision!==plan.view.revision||current?.version_id!==plan.view.version_id)box.append(node('p','The current view changed. Load its current selection before starting another comparison.','notice'));
}
async function loadChangeHistory(before=null){
 const result=await api('/api/changes'+(before?'?before='+before:''));s.changeHistory=result;s.changeHistoryBefore=before;
 const body=$('change-history');body.replaceChildren();
 for(const report of result.comparisons){const row=node('tr');cell(row,stamp(report.created_at));cell(row,report.view||'—');cell(row,report.status+(report.error?' · '+report.error:''));cell(row,report.counts?Object.entries(report.counts).filter(([key])=>key!=='unchanged').map(([key,value])=>key+': '+value).join(' · '):'—');cell(row).append(button('Open',()=>report.status==='COMPLETE'?openComparison(report.id):openJob(report.id)));body.append(row);}
 if(!result.comparisons.length)empty(body,5,'No retained comparisons yet.');
 $('change-history-page').textContent='History page '+(s.changeHistoryPages.length+1)+' · newest first';
}
async function changePage(comparisonId,kind='all',after=0,pages=[]){
 const sequence=++s.changeLoad;
 try{
  const result=await api('/api/changes/'+comparisonId+'?kind='+encodeURIComponent(kind)+'&after='+after);
  if(sequence!==s.changeLoad)return;
  const changed=s.change?.report.id!==comparisonId;s.change=result;s.changePages=pages;
  if(changed){let note='';try{note=localStorage.getItem('sf-change-note:'+s.data.workspace_id+':'+comparisonId)||'';}catch{}$('change-note').value=note;}
  if(result.selection)$('change-note').value=result.selection.note;
  renderComparison();
 }catch(error){if(sequence===s.changeLoad&&s.change)$('change-kind').value=s.change.kind;throw error;}
}
async function openComparison(comparisonId){await changePage(comparisonId);tab('changes');}
function selectionInfo(){
 const value=s.change,report=value?.report;if(!report)return;
 const current=s.data?.views.find(v=>v.name.toLowerCase()===report.reviewed_view.name.toLowerCase());
 const now=current?'Current view '+current.name+' selects '+short(current.version_id)+' at revision '+current.revision+'.':'The reviewed view no longer exists.';
 $('change-selection').textContent=(value.selection?'This comparison was selected at '+stamp(value.selection.selected_at)+' as revision '+value.selection.activation.revision+'. ':current?.revision===report.reviewed_view.revision&&current?.version_id===report.reviewed_view.version_id?'Selecting applies the candidate to '+report.reviewed_view.name+' using reviewed revision '+report.reviewed_view.revision+'. ':'The current view has changed since this comparison. Start a new comparison to review its current selection. ')+now;
}
function renderComparison(){
 const value=s.change,report=value.report;$('change-report').hidden=false;$('change-kind').value=value.kind;
 $('change-report-info').textContent=stamp(report.completed_at)+' · '+report.id+' · complete';
 const counts=$('change-counts');counts.replaceChildren();
 for(const [key,count]of Object.entries(report.counts)){const item=node('div');item.append(node('strong',String(count)),node('span',key));counts.append(item);}
 const schema=$('change-schema');schema.replaceChildren();fact(schema,'Matching keys',report.keys.join(', '));fact(schema,'Columns added',report.schema_changes.added.join(', ')||'None');fact(schema,'Columns removed',report.schema_changes.removed.join(', ')||'None');fact(schema,'Rows reordered',report.positions_changed);
 for(const changed of report.schema_changes.original_json_types)fact(schema,'JSON type · '+changed.column,changed.before.join(', ')+' → '+changed.after.join(', '));
 $('change-binding').textContent=JSON.stringify({reviewed_view:report.reviewed_view,baseline:{version_id:report.baseline.version_id,dataset:report.baseline.dataset,manifest_sha256:report.baseline.manifestSha256,rows:report.baseline.row_count},candidate:{version_id:report.candidate.version_id,dataset:report.candidate.dataset,manifest_sha256:report.candidate.manifestSha256,rows:report.candidate.row_count},value_basis:report.value_basis,result_sha256:report.result_sha256,rows_sha256:report.rows_sha256},null,2);
 const box=$('change-rows');box.replaceChildren();
 for(const record of value.rows){
  const detail=node('details',undefined,'change-record'),summary=node('summary',record.kind.toUpperCase()+' · '+record.key.map((c,i)=>report.keys[i]+'='+c.text+' ('+c.type+')').join(', ')+' · row '+scalar(record.before_row_number)+' → '+scalar(record.after_row_number));detail.append(summary);
  const wrap=node('div',undefined,'table-scroll'),table=node('table'),head=node('thead'),tr=node('tr');for(const label of ['Column','Baseline','Candidate'])tr.append(node('th',label));head.append(tr);table.append(head);const body=node('tbody');
  for(let i=0;i<report.columns.length;i++){const row=node('tr');cell(row,report.columns[i],'code');for(const values of [record.before,record.after]){const value=values?.[i]||{type:'missing',text:''},td=cell(row,value.type==='missing'?'Absent':value.type==='null'?'NULL':value.text,'code');td.append(node('span',value.type,'change-type'));}body.append(row);}
  table.append(body);wrap.append(table);detail.append(wrap);box.append(detail);
 }
 if(!value.rows.length)box.append(node('p',report.changed_rows?'No changes in this category.':'No acquired row values or positions differ. Review schema and acquisition differences above.'));
 $('change-page').textContent='Page '+(s.changePages.length+1)+' · '+value.rows.length+' shown · '+report.changed_rows+' complete retained differences'+(value.kind==='all'?'':' · '+value.kind);
 selectionInfo();controls();
}
async function selectComparison(){
 const value=s.change,report=value.report,note=$('change-note').value,key='sf-change-request:'+s.data.workspace_id+':'+report.id;
 let pending;try{pending=JSON.parse(localStorage.getItem(key));}catch{}
 if(!pending||pending.result_sha256!==report.result_sha256||pending.note!==note)pending={id:id(),result_sha256:report.result_sha256,note};
 try{localStorage.setItem(key,JSON.stringify(pending));}catch{}
 const selected=await api('/api/changes/'+report.id+'/select',pending);
 try{localStorage.removeItem(key);}catch{}
 await refresh();await changePage(report.id,value.kind,value.after,s.changePages);
 message('Reviewed candidate selected for '+selected.activation.name+' at revision '+selected.activation.revision+'. Continue with the current view in Analysis.');
}
async function downloadComparison(){
 const job=s.changeDownload;if(!job)return;const result=job.result;
 let handle=null;if(window.showSaveFilePicker){try{handle=await window.showSaveFilePicker({suggestedName:result.filename});}catch(error){if(error.name==='AbortError')return;throw error;}}
 const response=await fetch('/api/change-export/'+job.id,{headers:{'X-Analysis-Capability':capability},cache:'no-store'});
 if(!response.ok){const error=await response.json();throw Error(error.error||'Download failed');}
 if(handle){const writable=await handle.createWritable();try{await response.body.pipeTo(writable);}catch(error){await writable.abort().catch(()=>{});throw error;}}
 else{
  if(Number(response.headers.get('Content-Length'))>64*1024*1024){await response.body.cancel();throw Error('This browser cannot stream a report this size to a file. The complete export is retained at '+result.path+'. Use a browser with the file-save API or copy that retained file.');}
