  function controls(){const unavailable=s.busy||!s.data;for(const name of ['workbook-new','workbook-saved','workbook-revision','workbook-name','workbook-title','workbook-notes','workbook-source-kind','workbook-source','workbook-source-refresh','workbook-save','workbook-preview','workbook-build','workbook-history-refresh','workbook-preview-sheet','workbook-detail-definition'])$(name).disabled=unavailable;$('workbook-add').disabled=unavailable||!w.sources?.items.some(item=>item.available!==false)||w.editor.sheets.length>=32;$('workbook-save').disabled||=!w.editor.sheets.length;$('workbook-preview').disabled||=!w.loaded||changed();$('workbook-build').disabled||=!w.loaded||changed()||!!s.active;$('workbook-cancel').disabled=unavailable||!w.active;$('workbook-source-prev').disabled=unavailable||!w.sourcePages.length;$('workbook-source-next').disabled=unavailable||!w.sources?.next_before;$('workbook-history-prev').disabled=unavailable||!w.pages.length;$('workbook-history-next').disabled=unavailable||!w.history?.next_before;for(const control of document.querySelectorAll('#workbook-sheets input,#workbook-sheets select'))control.disabled=unavailable;editionControls();}
