  $('workbook-source-kind').addEventListener('change',()=>act(()=>sources()));$('workbook-source').addEventListener('change',()=>{sourceInfo();controls();});
  $('workbook-source-refresh').addEventListener('click',()=>act(()=>sources()));$('workbook-source-next').addEventListener('click',()=>act(()=>sources(w.sources.next_before,[...w.sourcePages,w.sourceBefore])));$('workbook-source-prev').addEventListener('click',()=>act(()=>sources(w.sourcePages.at(-1),w.sourcePages.slice(0,-1))));
