}
async function run(label,operation) {
  if(state.busy) return;
  state.busy=true;
  document.querySelectorAll('button').forEach(function(button){button.disabled=true;});
  notice(label+'…');
  try { await operation(); }
  catch(error) { notice(error.message||String(error),'error'); }
